quests[264] = { id = 264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bis dass der Tod uns scheidet", description = "Dreckiger Abschaum! Lässt mich wegen seines verdammten Kreuzzugs hier sitzen. Nur, weil \"das Licht das Wichtigste ist, was wir gegen die Bedrohung durch die Untoten besitzen\".\n\nUnd was ist mit seinen Kindern?! Was ist mit MIR?! Nacht für Nacht hab ich hier gesessen und geduldig auf ihn gewartet... hab immer den zweiten Platz hinter seiner verfluchten Pflicht eingenommen!\n\nTja, hier könnt Ihr sehen, was Euch Gerechtigkeit einbringt, {name}! Er ist tot und ich ertrage genau das, was er aufzuhalten versuchte!\n\nNehmt diesen Plunder und legt ihn auf seine Gruft im Grabmal. Ich will nichts mehr damit zu tun haben... oder mit ihm!", sourceObjective = "Legt Clarices Anhänger auf Yurivs Grab im Silberwald.", progress = "Der Stein fühlt sich kalt an, wurde aber offensichtlich misshandelt. Überall liegt Abfall herum; Scharten und Risse überziehen das Relief auf dem Sarg; und das Gestrüpp ringsherum hat schon begonnen, das Grab zu überwuchern.\n\nNiemanden kümmert es, wer hier begraben liegt, am allerwenigsten etwaige Opfer der Seuche.", completion = "Ihr legt den wertlosen Anhänger auf das Grab und der darin eingelassene Edelstein scheint merklich zu verblassen.\n\nAls Ihr aufsteht, um zu gehen, seht Ihr auf den Anhänger herab. Er liegt leblos über den Händen des Reliefs, das in die Oberseite des Sarges geschnitzt ist. Eure Gedanken werden kurz unterbrochen, als ein steifer, kalter Windhauch über das Grabmal weht. Für einen Moment ist alles um Euch herum still.", sourceObjectiveStatus = "unverified-source-field" }
quests[265] = { id = 265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schattensuche geht weiter", description = "Hier habt Ihr Euer Buch zurück, {name}, und viel Glück noch bei Eurer Suche. Vielleicht können Euch ja andere in der Stadt mehr Hinweise geben, wenn Ihr sie fragt.\n\nIch habe jedenfalls noch einen für Euch - obwohl der Autor dieses Buches in Dunkelhain fremd ist, wurde das Buch selbst hier gekauft.", sourceObjective = "Überprüft, ob andere Einwohner Hinweise auf die schattenhafte Gestalt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[266] = { id = 266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachforschungen im Gasthaus", description = "Hier habt Ihr Euer Buch zurück, und noch viel Glück bei Euren Nachforschungen.\n\nVielleicht wollt Ihr Eure Suche auf das Gasthaus ausweiten. Wenn die Person, die Ihr sucht, einige Zeit hier in der Stadt verbracht hat, dann hat sie dort vielleicht jemand gesehen.", sourceObjective = "Sucht im Gasthaus nach Hinweisen auf die schattenhafte Gestalt.", sourceObjectiveStatus = "unverified-source-field" }
quests[267] = { id = 267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bedrohung durch die Troggs", description = "{class}, Ihr seid Euch vielleicht nicht unbedingt der Bedrohung durch die Troggs bewusst, die ihren Schatten über das Land der Zwerge wirft. Nachdem die Reserve von Eisenschmiede zur Front der Allianz gerufen wurde, bleibt uns nur ein Bruchteil der Verteidigungskräfte, die nötig wären, um dieses Land zu schützen. Meinem Regiment wurde aufgetragen, über das Tor hier zu wachen, und wir können unseren Posten aufgrund der Gefahr einer Invasion nicht verlassen.\n\nEs muss aber etwas Druck auf diese verdammten Troggs ausgeübt werden, die in den Hügeln lauern. Wenn Ihr Euch dem gewachsen fühlt, startet einen Angriff auf die Troggs. Bringt mir 8 Troggsteinzähne als Beweis.", sourceObjective = "Bringt Hauptmann Rugelfuß im südlichen Wachturm 8 Troggsteinzähne.", sourceObjectiveStatus = "unverified-source-field" }
quests[268] = { id = 268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Sven", description = "Das Buch, das Ihr gefunden habt, war nur zur Hälfte fertig geschrieben. Ich musste es auf Svens Hof zurücklassen, als ich hierher floh... \n\nHier. Nehmt mein vollständiges Tagebuch und bringt es zu Sven. Es beschreibt wesentlich genauer, was auf seinem Hof passierte.\n\nObwohl dieses Tagebuch in den letzten Wochen meine einzige Gesellschaft war, gebe ich es gern auf, wenn ich mir dadurch erspare, Sven und seiner Wut zu begegnen.", sourceObjective = "Kehrt mit Bibbers' vollständigem Tagebuch zu Sven zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[269] = { id = 269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Weisheit", description = "Geht nach Sturmwind und sprecht dort mit Bischof Heller in der Kathedrale des Lichts. Gebt ihm Bibbers' Tagebuch und sagt ihm, dass Ihr vorhabt, Euch Morbent Teufel zu stellen.\n\nAuch wenn Sturmwind Dunkelhain aufgegeben hat, ist Heller doch eine gute Seele und sehr weise. Er könnte Euch bei Eurem Versuch, uns zu retten, behilflich sein.\n\nEure Mission ist gefahrvoll, aber beeilt Euch dennoch, {name}. Mit jeder verstreichenden Stunde verfinstern sich die Schatten über dem Dämmerwald mehr und mehr.", sourceObjective = "Gebt Bischof Heller in Sturmwind Bibbers' vollständiges Tagebuch.", sourceObjectiveStatus = "unverified-source-field" }
quests[270] = { id = 270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verlorene Flotte", description = "Vor vielen Jahren sank die dritte Flotte von Kul Tiras vor der Küste des Sumpflandes, einem Moorgebiet nördlich des Zwergenkönigreichs von Eisenschmiede. Auf einem der Schiffe befand sich eine Ladung lichtgeschmiedetes Eisen.\n\nDieses Metall ist wertvoll für uns, da Gegenstände, die daraus gefertigt werden, mit heiliger Wahrheit zuschlagen. Wenn Ihr Morbent Teufel entgegentreten wollt, dann werdet Ihr eine solche Waffe brauchen.\n\nGeht zum Hafen von Menethil und sprecht mit meinem zwergischen Kollegen Glorin Stahlbraue. Wenn dieses verlorene Metall überhaupt gefunden werden kann, dann weiß er, wo man danach suchen muss.", sourceObjective = "Geht zum Hafen von Menethil im Sumpfland und sprecht mit Glorin Stahlbraue.", sourceObjectiveStatus = "unverified-source-field" }
quests[271] = { id = 271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vyrins Rache", description = "Ihr seid nicht zufällig daran interessiert, es unserem ach so kühnen Kühnen ein wenig heimzuzahlen? Es schmerzt mich, das zu sagen, aber Daryl hat ein gewisses Talent.\n\nVor einem Jahr war ein großer Bär das Ziel der Jagdhütte der Weltenwanderer, aber keiner der Jäger hatte Glück mit ihm. Also dachte sich Daryl, er könnte sich mal an ihm versuchen. Das Einzige, was er nach seinem Versuch vorweisen konnte, war die hässliche Narbe über seinem Auge.\n\nErlegt den Bären und ich bin mir sicher, dass sogar Daryl mal sprachlos wäre.\n\nAlte Rußtatze, der Bär, hält sich irgendwo in der Nähe seines Baus nördlich von hier auf.", sourceObjective = "Tötet alte Rußtatze und zeigt Daryl dem Jüngling in der Jagdhütte der Weltenwanderer dann Euer Werk.", sourceObjectiveStatus = "unverified-source-field" }
quests[272] = { id = 272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prüfung des Seelöwen", description = "Für die zweite Prüfung benötigt Ihr die zwei Hälften, aus denen der Anhänger des Seelöwen besteht. Die eine Hälfte bezieht ihre Kraft aus der Beweglichkeit des Seelöwen-Aspektes beim Gleiten durchs Wasser; die andere Hälfte bezieht ihre Kraft aus der unglaublichen Ausdauer des Seelöwen-Aspektes. Druiden bedienen sich dieser beiden Eigenschaften gleichermaßen, um den Aspekt ihrer Wassergestalt zu verkörpern.\n\nSprecht mit den Bewohnern der Mondlichtung, um herauszufinden, wo sich die Teile befinden könnten, und bringt beide hierher, um sie miteinander zu vereinen. Bringt den Anhänger zu Dendrite Sternenschauer, wenn Ihr ihn geschaffen habt.", sourceObjective = "Sucht die Anhängerhälfte der Wasserbeweglichkeit und die Anhängerhälfte der Wasserbelastbarkeit. Sprecht mit den Einwohnern der Mondlichtung, um Hinweise darauf zu erhalten, wo sich diese Gegenstände befinden könnten.\n\nFormt den Anhänger des Seelöwen aus den beiden Anhängerhälften. Ihr müsst in der unmittelbaren Nähe des Schreins von Remulos sein, um dies zu tun.\n\nBringt den zusammengefügten Anhänger zu Dendrite Sternenschauer nach Nachthafen auf der Mondlichtung.", sourceObjectiveStatus = "unverified-source-field" }
quests[273] = { id = 273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachschub für die Ausgrabungsstätte", description = "Es ist noch nicht zu spät, Ihr könnt gern losziehen und Huldar suchen. Er kann noch nicht sehr weit gekommen sein, denn so stark sie auch sein mögen, können Miran und Saean dennoch nicht allzu schnell laufen, wenn sie mit diesen Fässern vollgepackt sind.\n\nSie nehmen die übliche Route zur Ausgrabungsstätte, südwärts aus der Stadt raus und dann an der Krümmung des Lochs entlang.\n\nIhr solltet keine Probleme haben, sie zu finden, solange sie nicht bereits dort angekommen sind.", sourceObjective = "Sprecht mit Huldar.", sourceObjectiveStatus = "unverified-source-field" }
quests[274] = { id = 274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine dunkle Bedrohung", description = "Und jetzt bringt Ihr diese Mixtur schnell zum Chefingenieur zurück. Die Dunkeleisen werden keine Zeit verlieren, also werden wir das auch nicht.", sourceObjective = "Ashlan Schmunzelstein möchte, dass Ihr mit der Entschärfungsmixtur zum Chefingenieur Hinderweir zurückkehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[275] = { id = 275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwärendes Land", description = "Ich weiß nicht warum, aber irgendetwas schwärt im Sumpfland. Moorkrabbler haben sich dort ausgebreitet. Sie sind wie kranke, fiebrige Blasen auf dem Land, und um das Fieber zu besiegen, müssen sie erledigt und dem Sumpf wieder zugeführt werden.\n\nDie Moorkrabbler watscheln mitten in den Wasserwegen des Sumpflandes herum.", sourceObjective = "Tötet 8 Moorkrabbler und kehrt dann zu Rethiel dem Sumpfhüter im Sumpfland zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[276] = { id = 276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stapfende Pfoten", description = "Die Moosfellgnolle lebten viele Jahre friedlich im Sumpfland, aber in letzter Zeit wächst ihre Anzahl. Ihre Füße trampeln die Büsche und Blumen des Moores platt, und ihre garstigen Äxte schlagen zu viel Holz für ihre Feuer.\n\nSie befinden sich nicht mehr im Gleichgewicht mit dem Land. Wenn das Sumpfland überleben soll, müssen die Gnolle dezimiert werden.\n\nTötet 15 Gnolle der Moosfelle und 10 Bastarde der Moosfelle. Jagt sie im Süden, nahe dem Zwergentor von Algaz. Wenn Ihr das getan habt, kehrt zu mir zurück.", sourceObjective = "Tötet 15 Gnolle der Moosfelle sowie 10 Bastarde der Moosfelle und kehrt dann zu Rethiel dem Sumpfhüter im Sumpfland zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[277] = { id = 277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer-Tabu", description = "Die Moosfelle fällen die Bäume des Sumpflandes und verwenden das Fleisch der Bäume, um sich mit Feuer zu wärmen. Ich werde diesen Schmerz nicht länger ertragen!\n\nEntledigt die Moosfelle ihrer kunstlosen Feuersteine, der Werkzeuge, die sie zum Feuermachen verwenden. Die meisten Moosfelle tragen diese Feuersteine bei sich, ausgenommen die kleineren Gnolle der Moosfelle und Bastarde der Moosfelle.", sourceObjective = "Bringt Rethiel dem Sumpfhüter 9 kunstlose Feuersteine.", sourceObjectiveStatus = "unverified-source-field" }
quests[278] = { id = 278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine dunkle Bedrohung", description = "Fangt gleich damit an, die Stoffe zum Entschärfen zusammenzusuchen, {name}. Lauerergift kann von den einheimischen Spinnen gewonnen werden. Krokiliskentränen findet man ebenfalls hier im Loch. Ein Kristall der Mo'grosh hingegen dürfte sehr schwierig zu bekommen sein. Die Oger im Nordosten bauen sie ab, aber die Kristalle sind ein sehr seltener Rohstoff.\n\nWir müssen einen Angriff der Dunkeleisenzwerge abwehren können! Kommt zurück, wenn Ihr alle erforderlichen Dinge zusammenhabt, und ich werde die Mixtur vorbereiten.", sourceObjective = "Ashlan Schmunzelstein möchte, dass Ihr Lauerergift, einen Kristall der Mo'grosh und eine Krokiliskenträne besorgt.", sourceObjectiveStatus = "unverified-source-field" }
quests[279] = { id = 279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klauen aus der Tiefe", description = "Murlocs kriechen aus den tiefen Wassern und bauen ihre Dörfer entlang der Küste. Sie überfallen unsere Fischer und Händler und müssen aufgehalten werden.\n\nEiner dieser Murlocs, Gobbler, streift mit den anderen Murlocs der Blaukiemen umher und plündert die Händler entlang der Straße aus, wobei sie sich danach immer in die Sicherheit der nahegelegenen Hütten zurückziehen. Unsere Händler sind in Gefahr, und wir sind bereit, für ihre Sicherheit zu zahlen.\n\nGobbler strolcht in der kleinen Bucht nördlich von hier herum. Findet ihn, erschlagt seine Artgenossen und bringt mir seinen Kopf.", sourceObjective = "Tötet 12 Murlocs der Blaukiemen.\n\nErschlagt Gobbler und nehmt Euch seinen Kopf.\n\nBringt Gobblers Kopf zu Karl Boran in den Hafen von Menethil.", sourceObjectiveStatus = "unverified-source-field" }
quests[280] = { id = 280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine dunkle Bedrohung", description = "Heute habe ich einige Aufrührer der Dunkeleisenzwerge gesehen, die mit einem großen Fass in Richtung Damm geschwommen sind. Es waren keine Gebirgsjäger zur Hand, um sie aufzuhalten! Ich fürchte, sie haben das Zephyrium am Fuße des Dammes deponiert, und es könnte jede Minute hochgehen!\n\nIhr müsst jetzt diese Mixtur mitnehmen und in das Fässchen einrühren, bevor es zu spät ist! Beeilt Euch!", sourceObjective = "Chefingenieur Hinderweir will, dass Ihr zum Fuß des Dammes hinunterschwimmt, das Pulverfässchen ausfindig macht und die Entschärfungsmixtur hineinrührt, um eine Explosion zu verhindern.", sourceObjectiveStatus = "unverified-source-field" }
quests[281] = { id = 281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waren-Wiederbeschaffung", description = "Vor nicht allzu langer Zeit wurde ein Handelsschiff, die Blinde Prinzessin, von Murlocs überfallen. Obwohl das Schiff unversehrt entkam, wurde ein Großteil seiner Fracht von den Kreaturen über Bord gezogen, darunter eine äußerst wertvolle Statuette von Terenas Menethil. Wir möchten, dass die Statuette geborgen wird.\n\nDurchsucht die Hütten der Murlocs an der Küste nach Kisten, Fässern und anderen Spuren von verlorener Fracht. Findet die Statuette von Menethil und bringt sie mir wieder.", sourceObjective = "Durchsucht die Kisten und Fässer in den Murloclagern an der Küste.", sourceObjectiveStatus = "unverified-source-field" }
quests[282] = { id = 282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Senirs Beobachtungen", description = "Ich hatte ursprünglich vor, meinen Lehrling mit meinem Bericht zu meinem Bruder Senir zu schicken, aber ich würde mich viel besser fühlen, wenn er in etwas... verlässlicheren Händen wäre. Natürlich nur, wenn es Euch nichts ausmacht?\n\nHmm... Ihr müsstet den Tunnel nehmen, um nach Kharanos zu gelangen.\n\nSprecht mit Gebirgsjäger Thalos, bevor Ihr durch den Tunnel geht. Er ist mittlerweile vollständig von den Troggs überrannt.\n\nFolgt der Straße zurück nach Ambossar und geht dann weiter nach Osten zum Tunnel. Thalos ist ganz in seiner Nähe stationiert.", sourceObjective = "Sprecht mit Gebirgsjäger Thalos.", sourceObjectiveStatus = "unverified-source-field" }
quests[283] = { id = 283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine dunkle Bedrohung", description = "Das Fässchen zischt ein wenig.", sourceObjective = "Die Entschärfungsmixtur scheint gewirkt zu haben. Kehrt zu Chefingenieur Hinderweir zurück und berichtet ihm die guten Neuigkeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[284] = { id = 284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche geht weiter", description = "Ihr durchsucht gründlich diese Ansammlung von Murlochütten, findet aber keine Spur der Statuette von Menethil.\n\nVielleicht gibt es in einer der beiden nahe gelegenen Hütten im Norden und Nordosten mehr Hinweise.", sourceObjective = "Sucht nach der Statuette von Menethil.", sourceObjectiveStatus = "unverified-source-field" }
quests[285] = { id = 285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche in weiteren Hütten", description = "Dieses Grüppchen Murlochütten offenbart auch nach einer gründlichen Überprüfung nichts.\n\n... Aber Ihr seid Euch sicher, dass der nächste Anhaltspunkt, den Ihr findet, nützlich sein wird.\n\nEine der Hütten nördlich von hier muss die Statuette von Menethil enthalten!", sourceObjective = "Sucht weiter in den Hütten der Murlocs nach der Statuette von Menethil.", sourceObjectiveStatus = "unverified-source-field" }
quests[286] = { id = 286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückgabe der Statuette", description = "Nachdem Ihr das Fass aus dem Dreck gezogen und geöffnet habt, findet Ihr eine in dünnes Stroh eingepackte, silbrige Figur. Sie stellt einen jungen, langhaarigen Paladin mit erhobenem Hammer dar.\n\nDies kann nur die Statuette von Menethil sein! Ihr müsst sie nun zu Karl Boran in den Hafen von Menethil zurückbringen.", sourceObjective = "Bringt Karl Boran im Hafen von Menethil im Sumpfland die Statuette von Menethil.", sourceObjectiveStatus = "unverified-source-field" }
quests[287] = { id = 287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höhle der Frostmähnen", description = "Ich bin mit meinem Bericht etwas im Rückstand und könnte Eure Hilfe brauchen, {name}. Ich habe gerade herausgefunden, wo sich die Trolle verschanzt haben, aber ich habe so viele Trolle gesehen, dass ich mich nicht getraut habe, hineinzugehen.\n\nWas ich von Euch möchte, ist Folgendes: Geht runter zur Höhle, schaut Euch ein wenig darin um, tötet ein paar Trolle und kommt dann wieder hierher zurück.\n\nNehmt die Straße nach Norden, raus aus Kharanos. Sobald Ihr an der Brücke ankommt, folgt dem zugefrorenen Fluss westwärts, bis Ihr den Eiswellensee erreicht. Am linken Ufer werdet Ihr Bräuhall vorfinden. Die Höhle liegt südwestlich des Dorfes.", sourceObjective = "Erforscht die Höhle der Frostmähnen und tötet 5 Kopfjäger der Frostmähnen für Senir Weißbart in Kharanos.", sourceObjectiveStatus = "unverified-source-field" }
quests[288] = { id = 288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dritte Flotte", description = "Ich war einst Erster Maat auf der 'Herrin der Meere', einem Linienschiff der Dritten Flotte von Kul Tiras, der Verlorenen Flotte. Verloren deshalb, weil die Flotte auf ihrer letzten Reise von roten Großdrachen angegriffen wurde. Großdrachen, die von Orcs beherrscht wurden!\n\nWir hatten keine Chance gegen das Drachenfeuer... und unsere Flotte ging just vor dieser Küste hier brennend unter. Ich bin der einzige Überlebende von diesen armen Schiffen.\n\n... Oh, mir brummt der Schädel! Ich werde einen frischen Drink brauchen, wenn ich mit diesem Kater klarkommen und meine Geschichte fortsetzen soll.", sourceObjective = "Spendiert dem Ersten Maat Fitzsimmons einen Krug Met.", sourceObjectiveStatus = "unverified-source-field" }
quests[289] = { id = 289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verfluchte Crew", description = "<Gestärkt setzt Fitzsimmons seine Geschichte fort...>\n\nIch bin der einzige Überlebende der unglückseligen Dritten Flotte von Kul Tiras, die vor der Küste im Norden vernichtet wurde. Aber obwohl ich das einzige Mitglied der Flotte bin, das noch atmet, bin ich nicht der einzige, der noch herumläuft! Denn auf einem unserer Schiffe war ein großer und schrecklicher Schatz versteckt, und dessen unheimliche Macht hält die Seelen meiner Brüder in den verrottenden Wracks gefangen.\n\nWenn Ihr allerdings einige meiner Brüder befreien könnt, könnt Ihr vielleicht auch den Fluch brechen, der auf ihnen lastet.", sourceObjective = "Vernichtet 13 verfluchte Seeleute, 5 verfluchte Marinesoldaten und den Ersten Maat Snellig. Bringt Snelligs Schnupftabakdose zum Ersten Maat Fitzsimmons im Hafen von Menethil.", sourceObjectiveStatus = "unverified-source-field" }
quests[290] = { id = 290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brechen des Fluchs", description = "Um den Fluch zu brechen und alle meine Brüder zu befreien, müsst Ihr das... Ding..., das auf meinem Schiff verstaut ist, bergen und reinigen! Ich weiß nicht, was es war, aber ich weiß, dass es sicher in der Geldkassette des Schiffs verwahrt wurde, zu dem nur Kapitän Halyndor den Schlüssel hatte.\n\nMein alter Kapitän erscheint mir immer noch in meinen Träumen. Ich bin mir sicher, dass er auf meinem untergegangenen Schiff, der 'Kühnheit', herumläuft. Besorgt Euch den Schlüssel von ihm und öffnet damit die Geldkassette der 'Kühnheit'.\n\nAnschließend, wenn Ihr das verfluchte Ding habt, bringt es zu Glorin Stahlbraue, dem Priester, hier in der Stadt.", sourceObjective = "Besorgt den Geldkassettenschlüssel der 'Kühnheit' von Kapitän Halyndor.\n\nVerwendet den Schlüssel, um die Geldkassette der 'Kühnheit' zu öffnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[291] = { id = 291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Berichte", description = "Wunderbar! Überbringt Senator Barin Rotstein meinen Bericht. Er ist ein missmutiger Geselle, also stört Euch nicht an seinem wenig sonnigen Gemüt. Er ist in Eisenschmiede, in der Halle, in der König Magni Hof hält.\n\nIhr kennt den Weg nach Eisenschmiede nicht? Nehmt die Straße aus Kharanos heraus nach Norden, überquert die Brücke und folgt dann der Straße nach Osten den Berghang hinauf. Einige große Banner flankieren diese Straße.\n\nAch ja, und könntet Ihr es vielleicht vermeiden, zu erwähnen, dass Ihr mir geholfen habt? Ich kann die ja nicht glauben lassen, ich würde hier draußen nicht hart arbeiten, nicht wahr?", sourceObjective = "Überbringt Senator Barin Rotstein in Eisenschmiede Senirs Bericht.", sourceObjectiveStatus = "unverified-source-field" }
quests[292] = { id = 292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge von Paleth", description = "In der offenen Truhe erblickt Ihr eine geschwärzte Kugel, die in einem gruseligen Licht pulsiert. Dies ist der Schatz, von dem Fitzsimmons gesprochen hat: ein verfluchtes Auge von Paleth.\n\nBringt das verfluchte Auge von Paleth zum Zwergenpriester Glorin Stahlbraue im Hafen von Menethil. Fragt ihn, wie man den Fluch des Auges brechen kann.", sourceObjective = "Bringt Glorin Stahlbraue im Hafen von Menethil im Sumpfland das verfluchte Auge von Paleth.", sourceObjectiveStatus = "unverified-source-field" }
quests[293] = { id = 293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung des Auges", description = "Ich kann den Fluch nicht von dem Auge von Paleth nehmen. Die Augen wurden von Menschenpriestern hergestellt, daher werdet Ihr nach Sturmwind gehen müssen, um jemanden zu finden, der Euch helfen kann. Sprecht mit Erzbischof Benedictus. Er steht der Kathedrale des Lichts in Sturmwind vor. Er kann helfen.\n\nDas hoffe ich jedenfalls, um Euretwillen.", sourceObjective = "Bringt Erzbischof Benedictus das verfluchte Auge von Paleth. Ihr findet Benedictus in der Kathedrale des Lichts, in der Stadt Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[294] = { id = 294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ormers Rache", description = "Die Lage ist ernst, so viel ist sicher. Als wir diese Knochen freigelegt haben, hat das die Raptoren angelockt. Diese dreckigen Bestien haben meine Brüder getötet und mich, Merrin und den armen Ausgrabungsleiter hier festgesetzt.\n\nHelft mit, das Sumpfland von diesen Raptoren zu säubern, {name}. Scheckige Raptoren und scheckige Kreischer befinden sich direkt westlich der Klippe hier. Tötet jeweils 10, wenn Ihr könnt.\n\nDas wäre ein guter Anfang für die Rache, die ich mir für sie ausgedacht habe.", sourceObjective = "Ormer Eisenzopf von Whelgars Ausgrabungsstätte möchte, dass Ihr 10 scheckige Kreischer und 10 scheckige Raptoren tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[295] = { id = 295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ormers Rache", description = "Es ist an der Zeit, diese abscheulichen Raptoren ihren Blutdurst bereuen zu lassen. Gleich da unten gibt es Dutzende von scheckigen Sensenklauen- und Scharfzahnraptoren. Lasst diese scheußlichen Kreaturen bezahlen, indem Ihr 10 von jeder Sorte erschlagt.", sourceObjective = "Ormer Eisenzopf möchte, dass Ihr 10 scheckige Sensenklauen- und 10 scheckige Scharfzahnraptoren tötet und dann zu ihm zu Whelgars Ausgrabungsstätte zurückkommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[296] = { id = 296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ormers Rache", description = "Während Ihr da unten wart, ist mir aufgefallen, dass eines der Biester aus der Menge herausstach. Es war größer und bedrohlicher. Ich könnte wetten, das ist derjenige, der die anderen hierher geführt hat und für die Störung der Ausgrabungsstätte verantwortlich ist.\n\nIch erbitte eine letzte Aufgabe von Euch, {name}. Sorgt dafür, dass Sarlatan seine gerechte Strafe erhält. Und wenn man die Schwere seiner Verbrechen bedenkt, bedeutet Gerechtigkeit in diesem Falle den Tod! Bringt mir eine seiner Krallen als Beweis, dass er tot ist.", sourceObjective = "Ormer Eisenzopf von Whelgars Ausgrabungsstätte möchte, dass Ihr Sarlatan tötet und mit einer seiner Krallen zu ihm zurückkehrt, sobald Ihr die Aufgabe erledigt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[297] = { id = 297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Götzen sammeln", description = "Vor einer Weile, kurz bevor die Troggs in der Ausgrabungsstätte auftauchten, hatten wir eine große Anzahl seltsame, verzierte Götzen gefunden. Leider hatten wir keine Gelegenheit, sie zu untersuchen, denn kurz nach ihrer Entdeckung haben uns die Troggs aus den Ruinen verjagt. Und diese Götzen haben eine seltsame Wirkung auf die Troggs. Sie verfallen dadurch in Raserei!\n\nBringt mir 8 Götzen - ich möchte sie studieren, und ich will sie nicht mehr in den Händen der Troggs sehen. Ihr könnt die Götzen bei den Troggs finden, die die Stätte heimsuchen.", sourceObjective = "Bringt Magmar Todesstreich an der Eisenband Ausgrabungsstätte 8 verzierte Steingötzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[298] = { id = 298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht über den Fortschritt der Ausgrabungen", description = "Ich muss einen Fortschrittsbericht nach Thelsamar schicken - einen Fortschrittsbericht und eine Neufassung meiner Anfrage nach mehr Sprengpulver! Hier ist der Bericht. Bringt ihn Jern Hornhelm. Er ist unser örtlicher Kontaktmann in Thelsamar.\n\nKeine schwierige Aufgabe, aber sie muss erledigt werden.", sourceObjective = "Bringt Eisenbands Fortschrittsbericht zu Jern Hornhelm in Thelsamar.", sourceObjectiveStatus = "unverified-source-field" }
quests[299] = { id = 299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enthüllung der Vergangenheit", description = "Kurz vor der Invasion habe ich eine große Schrifttafel gefunden, die man den Goazstein nennt. Der übersetzte Text reißt an 4 Stellen ab. Der Text spricht von einem \"göttlichen Plan\" und einer \"schicksalhaften Prophezeiung\".\n\nIch fürchte, uns läuft die Zeit davon. Ich bin zu alt, um hinunterzugehen und diesen Bestien zu trotzen. Aber Ihr seid stark.\n\nDurchkämmt die Ausgrabungsstätte und sucht die 4 fehlenden Tafelfragmente: Ados, Modr, Golm und Neru. Sucht sie in alten Artefakten oder dort, wo das Erdreich locker ist. Bringt sie mir, auf dass ich damit beginnen kann, ihre Geheimnisse zu enträtseln!", sourceObjective = "Ausgrabungsleiter Whelgar wünscht, dass Ihr die Ausgrabungsstätte nach den 4 fehlenden Tafelfragmenten durchkämmt, Ados, Modr, Golm und Neru.", sourceObjectiveStatus = "unverified-source-field" }
quests[301] = { id = 301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung in Eisenschmiede", description = "Wir werden eine Bewilligung brauchen, um Eisenband mehr Sprengpulver zu beschaffen. Ihr müsst seinen Bericht zum Hauptquartier der Forscherliga in Eisenschmiede bringen.\n\nHier ist der Bericht. Gebt ihn Ausgrabungsleiter Sturmlanze und vergesst nicht, Euch zu ducken, nachdem Ihr ihn abgeliefert habt. Sturmlanze ist ein Hitzkopf, und es wird ihn nicht erfreuen, wenn er von Eisenbands langsamem Vorankommen an der Ausgrabungsstätte hört.\n\nIhr findet Sturmlanze in der Versammlungshalle der Forscher.", sourceObjective = "Bringt Eisenbands Fortschrittsbericht zu Ausgrabungsleiter Sturmlanze.", sourceObjectiveStatus = "unverified-source-field" }
quests[302] = { id = 302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pulver für Eisenband", description = "Wenn Eisenband immer noch Sprengpulver braucht, dann, bei Magni, soll er es haben! Ich habe die Bewilligung bereits mit einem Boten nach Thelsamar zu Jern Hornhelm vorausgeschickt. Er wird das Pulver und andere Vorräte zum Transport zu Eisenband bereitstellen.\n\nAch, und noch was: Ich will, dass Ihr persönlich dafür Sorge tragt, dass diese Pulverlieferung ihren Bestimmungsort erreicht. Die letzte kam nicht an, also haltet Euren Verstand wach und Eure Augen offen.", sourceObjective = "Sprecht in Thelsamar mit Jern Hornhelm.", sourceObjectiveStatus = "unverified-source-field" }
quests[303] = { id = 303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Dunkeleisenkrieg", description = "Der Krieg tobt daheim ebenso wie in der Fremde. Während mächtige Zwergenkrieger im Namen der Allianz in weit abgelegenen Gegenden ihr Leben lassen, fallen unsere eigenen Gebiete den bösen Taten der Dunkeleisenzwerge zum Opfer. Sie haben den Thandolübergang verwüstet. Dun Modr fiel kurz darauf.\n\nIhr müsst Kräfte sammeln und die Front zurückdrängen. Wenn Ihr 10 Dunkeleisenzwerge, 5 Tunnelgräber der Dunkeleisenzwerge, 5 Saboteure der Dunkeleisenzwerge und 5 Demolierer der Dunkeleisenzwerge töten könnt, dann kommen die Reserven vielleicht rechtzeitig, um den Vormarsch zu beenden.\n\nUnd jetzt beeilt Euch!", sourceObjective = "Motley Garmason in Dun Modr möchte, dass Ihr 10 Dunkeleisenzwerge, 5 Tunnelgräber der Dunkeleisenzwerge, 5 Saboteure der Dunkeleisenzwerge und 5 Demolierer der Dunkeleisenzwerge tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[304] = { id = 304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine grausige Aufgabe", description = "Viele meiner Soldaten fielen in der Schlacht von Dun Modr. Mein eigener Bruder kam um, als die Westbrücke über dem Thandolübergang zerstört wurde. Jawohl, die Dunkeleisenzwerge sind eine teuflische Brut. Soweit Roggo das in Erfahrung bringen konnte, ist der Anführer dieses Verbrecherpacks im Sumpfland ein Hexenmeister namens Balgaras der Niederträchtige. Er ist allerdings ein ziemlicher Feigling. Er lässt seine Soldaten für sich kämpfen und versteckt sich selbst in seinem Lager auf dem Hügel der Düsterschmiede im Südosten.\n\nWenn Ihr diesen rückgratlosen Abschaum finden könnt, erschlagt ihn und bringt mir sein Ohr. Ich werde Euch dafür entlohnen, {class}.", sourceObjective = "Tötet Balgaras den Niederträchtigen und bringt Langzopf dem Grimmigen vor Dun Modr sein Ohr.", sourceObjectiveStatus = "unverified-source-field" }
quests[305] = { id = 305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach dem Ausgrabungstrupp", description = "Wie schön, Ihr müsst der Späher sein, den Langzopf zu schicken versprach. Ihr könnt Euch nicht vorstellen, wie besorgt ich war.\n\nMeine Frau, Merrin, hat mir im letzten Monat jede Woche Briefe geschickt. Sie gehört zu Whelgars Ausgrabungstrupp. Aber es sind fast zwei Wochen seit unserem letzten Briefwechsel vergangen. Irgendetwas ist bestimmt schief gelaufen!\n\nLangzopf versprach, dass er einen Späher schicken würde, der sich dort mal umsieht, wenn wir nicht bald etwas vom Trupp hören. Ich nehme mal an, dieser Späher seid Ihr, {name}. Findet Merrin in der Ausgrabungsstätte im Osten!", sourceObjective = "Tarrel Felsweber möchte, dass Ihr zur Ausgrabungsstätte reist und dort Kontakt mit Merrin Felsweber aufnehmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[306] = { id = 306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach dem Ausgrabungstrupp", description = "Es war grauenhaft! Wir hatten einige seltene Artefakte enthüllt und fingen an, welche von diesen großen Knochen zu finden.\n\nBevor wir wussten, wie uns geschah, überrannten diese scheckigen Raptoren die Ausgrabungsstätte. Viele ließen ihr Leben.\n\nOrmer hier rettete - ganz tapfer - den Ausgrabungsleiter und mich. Er verteidigte uns, während wir Schutz suchten. Jetzt sind wir gefangen. Und unsere harte Arbeit liegt in Trümmern.\n\nHier, nehmt diese Nachricht mit zurück zu meinem süßen Tarrel. Sie wird ihm die Situation klarmachen.", sourceObjective = "Kehrt mit Merrins Nachricht zu Tarrel Felsweber zurück. Zu finden ist er im Hafen von Menethil im Sumpfland.", sourceObjectiveStatus = "unverified-source-field" }
quests[307] = { id = 307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmutzige Pfoten", description = "Die Silberbachmine im Osten hat sich schon vor langer Zeit erschöpft. Sie wurde vom Bund der Bergarbeiter in ein Lagerhaus umgewandelt, aber jetzt sind dort Kobolde eingezogen und befingern mit ihren schmutzigen Pfoten gute zwergische Werkzeuge!\n\nWir werden dieses Ungeziefer noch früh genug ausmerzen, aber der Bund wünscht, dass jemand ihre Gerätschaften aus der Mine schafft, bevor wir Krieger da reinstürmen und was kaputtmachen. Das wird ein harter Abstieg – Ihr solltet vielleicht Unterstützung mitnehmen.\n\nDie Ausstattung wird in Kisten des Bergarbeiterbunds über die Mine verteilt aufbewahrt. Viel Glück.", sourceObjective = "Geht zur Silberbachmine und sucht 6 Sätze Minenarbeiterausstattung zusammen.\n\nKehrt dann zu Gebirgsjäger Sturmlanze zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[308] = { id = 308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jarvens Ablenkung" }
quests[309] = { id = 309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschützen der Fracht", description = "Wir müssen dieses Pulver zu Eisenband bringen, aber der Wagen fährt nirgendwo mehr hin. Es ist eine Menge zu schleppen und diese Gegend kann gefährlich sein; und wer weiß, was die Dunkeleisenzwerge für uns auf Lager haben nun da Saean zu ihnen gestoßen ist.\n\nMir wäre viel leichter zumute, wenn Ihr mit mir Ausschau halten könntet. Miran kann die Pulverfässer im Lager abladen während Ihr und ich den Wagen bewachen.", sourceObjective = "Beschützt Huldar und den Eisenbandkonvoi und erstattet anschließend Ausgrabungsleiter Eisenband Bericht.", completion = "Ihr bringt Besorgnis erregende Neuigkeiten. Wenn ich nur daran denke, dass die Dunkeleisenzwerge Sympathisanten haben, die solches Material für ihre heimtückischen Pläne beschaffen können.\n\nDoch das ist eine Angelegenheit, um die sich jemand anderes zu gegebener Zeit kümmern muss. Habt Dank, dass Ihr Huldar und den Wagen beschützt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[310] = { id = 310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bittere Rivalen", description = "Ich muss zugeben, diese Donnerbräus stellen ein paar gute Getränke her. Aber sie müssen noch lernen, dass ihres nicht das einzige ordentliche Gebräu ist! Vielleicht könnt Ihr mir helfen, ihnen diese Lehre zu erteilen...\n\nHier, nehmt dieses Fass mit Gerstenbräu. Schleicht Euch in den Keller der Brauerei Donnerbräu in Kharanos und vertauscht es mit einem ihrer Fässer Donnerbräu Lager. Dann werden wir ja sehen, ob ihre Kundschaft mein Gebräu lieber mag als ihres!\n\nAch ja, und falls die Fässer bewacht sein sollten, müsstet Ihr eventuell den Wächter irgendwie ablenken...", sourceObjective = "Vertauscht im Keller der Brauerei Donnerbräu in Kharanos ein Fass Donnerbräu Lager mit einem Fass Gerstenbräu.", sourceObjectiveStatus = "unverified-source-field" }
quests[311] = { id = 311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Marleth", description = "Nachdem Ihr ein Fass von Marleths Gerstenbräu im Keller der Brauerei Donnerbräu abgestellt habt, schnappt Ihr Euch zum Beweis ein Fass Donnerbräu Lager...", sourceObjective = "Bringt Marleth Gerstenbräu in Bräuhall das Fass mit Donnerbräu Lager.", sourceObjectiveStatus = "unverified-source-field" }
quests[312] = { id = 312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tundra MacGranns gestohlene Vorräte", description = "Ich hatte einen Monatsvorrat Trockenfleisch gesalzen und für die kalte Jahreszeit weggeschlossen. Weggeschlossen deshalb, damit die Bären nicht rankommen! Aber während ich unterwegs auf der Jagd war, hat sich diese Bestie, Eisbart der Alte, mit meiner Fleischtruhe davongemacht. Er wird allerdings nicht durch das Thorium kommen. Ich wiederum werde verhungern, wenn ich mein Fleisch nicht wiederbekomme.\n\nIhr seht gerissener aus als ich. Vielleicht könnt Ihr meinen Vorrat wiederbeschaffen? Ich würde es mit meinem steifen Bein niemals schnell genug in die Höhle hinein und wieder heraus schaffen.", sourceObjective = "Holt Tundra MacGranns Trockenfleisch aus der gestohlenen Fleischtruhe in der Höhle von Eisbart dem Alten.", sourceObjectiveStatus = "unverified-source-field" }
quests[313] = { id = 313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Zusehen verdammt", description = "Der Kataklysmus hat die Troggs in Scharen an die Oberfläche getrieben, sodass die Frostmähnentrolle um ihr Leben fliehen mussten. Leider haben sie sich entschieden, sich direkt vor unserer Nase niederzulassen und uns Ärger zu bereiten.\n\nIch habe Gebirgsjäger Dunstan und seinen Trupp zum Graufelsbau südwestlich der Stadt geschickt, um dort ein Auge auf die Wendigos zu haben, jetzt aber brauchen wir sie hier in Kharanos. Macht sie ausfindig und sagt ihnen, sie sollen diese ferngesteuerten Beobachtungsbots aufstellen und dann nach Kharanos zurückkehren.", sourceObjective = "Leitet Hauptmann Tharrans Befehle an Gebirgsjäger Dunstan, Gebirgsjäger Lewin und Gebirgsjäger Valgrum im Graufelsbau weiter.", completion = "Danke für Eure Hilfe, {name}. Unsere Truppen sind zurzeit weit verstreut und drei Gebirgsjäger könnten den Unterschied zwischen einer erfolgreichen Verteidigung von Kharanos und überrannt zu werden ausmachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[314] = { id = 314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herde beschützen", description = "Wir haben mitten in der Nacht die Schreie gehört. Heute morgen fehlten der Herde dann tatsächlich zwei Widder. Diese heimtückische Bestie, Vagash genannt, hat sich über unsere Existenzgrundlage hergemacht. Da der Großteil von König Magnis Armee irgendwo in weit entfernten Landen an der Seite der Allianz kämpft, ist niemand mehr da, der Vagash in Schach halten könnte.\n\nVielleicht seid Ihr tapfer genug, die Bestie aufzuspüren und zu erschlagen. Bringt mir einen seiner Fangzähne, und ich werde Euch belohnen. Vagash lauert direkt oberhalb des Hofs hier, aber seid gewarnt, die Bestie ist tödlich.", sourceObjective = "Erhaltet einen Fangzahn von Vagash.", progress = "Vagash terrorisiert immer noch die Herde! Bitte helft uns, indem Ihr die elende Bestie umbringt.", completion = "Sehr gut gemacht! Veron wird begeistert sein, wenn er die gute Nachricht vernimmt. Vagash zu töten, kann keine leichte Aufgabe gewesen sein. Ich schätze, Ihr werdet eines Tages Seite an Seite mit König Magnis Mannen an der Allianzfront kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[315] = { id = 315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das perfekte Starkbier", description = "Ich bin von einem Vorhaben besessen, dem Vorhaben, das perfekte Starkbier herzustellen. Ich weiß, dass ich es schaffen kann - das Brauen liegt mir im Blut. Ich muss nur das richtige Rezept finden...\n\nWeit oben in den Bergen im Nordwesten, auf dem Schimmergrat, bauen die Trolle der Frostmähnen eine Pflanze an, Schimmerkraut genannt. Sie verwenden sie in ihren seltsamen Stammesritualen. Wir Zwerge haben bisher keine wirkliche Verwendung dafür gefunden, aber sie hat einen einzigartigen Geschmack... und ich möchte damit in meinen Gebräuen herumexperimentieren.\n\nDas Schimmerkraut zu bekommen wird schwierig werden, aber ich werde Euch für jedes Schimmerkraut, das ihr aus den Körben im Trolldorf \"borgen\" könnt, gut bezahlen.", sourceObjective = "Bringt Rejold Gerstenbräu in Kharanos 7 Schimmerkräuter.", progress = "Habt Ihr das Schimmerkraut? Ich habe eine Fuhre Starkbier so gut wie braufertig und möchte das Kraut versuchsweise in diese Mischung mit hineinwerfen.", completion = "Großartig! Ich kann es kaum erwarten, sie in einigen meiner Rezepte auszuprobieren. Ich glaube, in ein bestimmtes würde es wunderbar hineinpassen...", sourceObjectiveStatus = "unverified-source-field" }
quests[317] = { id = 317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte für Dampfstrahl", description = "Ich bereite mich gerade darauf vor, eine Mission für die Belagerungsbrigade in Angriff zu nehmen. Sie wird ziemlich lange dauern, und ich muss Dampfstrahl mit Vorräten für einen ganzen Monat beladen. Könntet Ihr also nicht, während Stahlrost an meinem Panzer arbeitet, ein wenig für mich auf die Jagd gehen?\n\nIch werde ein paar Pelze als Bettzeug und etwas Eberfleisch zum Essen brauchen. Ihr könnt das Fleisch von Ebern und die Pelze von Bären erbeuten... Ihr findet beide in den Schneefeldern südlich des Graufelsbaus.", sourceObjective = "Sammelt 4 Brocken Eberfleisch und 2 dicke Bärenfelle und liefert sie bei Pilot Bellfiz in Stahlrosts Depot ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[318] = { id = 318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immerschimmer", description = "Rejold Gerstenbräu experimentiert mit seinen Gebräuen. Ein paar davon schmecken gut, einige schlecht, und einige... nun, einige hauen selbst den stärksten Zwerg um.\n\nEr lebt in Bräuhall, westlich von Kharanos, und ich will Immerschimmer, eines seiner Getränke. Es wird mich warmhalten, während ich in der Kälte unterwegs bin.\n\nAußerdem brennt das gesegnete Zeug so heiß, dass ich es in Dampfstrahls Brennofen kippen kann, um einen Energieschub zu erzeugen! Diese nette Taktik hat mich schon aus mehr als einer haarigen Situation gerettet.", sourceObjective = "Besorgt von Rejold Gerstenbräu in Bräuhall ein Fässlein Immerschimmer.", sourceObjectiveStatus = "unverified-source-field" }
quests[319] = { id = 319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gefallen für etwas Immerschimmer", description = "Ich habe ein Fässlein mit Immerschimmer zur Hand, aber... könnt Ihr mir einen Gefallen tun? Bräuhall könnte ein wenig Hilfe gebrauchen gegen die wilden Tiere, die die nahegelegenen Schneefelder durchstreifen. Manchmal kommen sie sehr nah.\n\nWir haben keine Angst vor diesen Bären und Katzen und Ebern - kein Zwerg, der etwas auf sich hält, hätte das - aber wenn Ihr Euch für uns um diese Tiere kümmern könntet, hätten wir mehr Zeit für unser Handwerk und unsere Braukunst.", sourceObjective = "Tötet 6 Eisklauenbären, 8 alte Klippeneber sowie 8 Schneeleoparden und kehrt dann zu Rejold Gerstenbräu nach Bräuhall zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[320] = { id = 320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Bellfiz", description = "Hier habt Ihr Euer Fässlein mit Immerschimmer, {name}. Und wie gesagt, vielen Dank für die Jagd kürzlich.", sourceObjective = "Gebt Pilot Bellfiz in Stahlrosts Depot das Fässlein mit Immerschimmer.", sourceObjectiveStatus = "unverified-source-field" }
quests[321] = { id = 321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lichtgeschmiedetes Eisen", description = "Diese Schiffswracks hier vor der Küste sind die verlorene Dritte Flotte von Kul Tiras, die während des letzten großen Krieges von roten Drachen verbrannt und versenkt wurde.\n\nDie Flotte stammte aus Lordaeron, bis auf ein Schiff, einen elfischen Zerstörer: die 'Fischadler'. Es transportierte eine Ladung lichtgeschmiedetes Eisen und schloss sich der Dritten Flotte aus Sicherheitsgründen an. Welche Ironie, dass es von denselben Drachen versenkt wurde... \n\nGenug Geschichte. Die 'Fischadler' liegt südlich vom Hafen von Menethil auf Grund. Wenn Ihr das lichtgeschmiedete Eisen darin finden könnt, bringt es zu mir.", sourceObjective = "Durchsucht das Wrack der 'Fischadler' im Sumpfland.", sourceObjectiveStatus = "unverified-source-field" }
quests[322] = { id = 322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesegnete Waffe", description = "Im Zwergendistrikt von Sturmwind gibt es einen zwergischen Waffenschmied, der lichtgeschmiedetes Eisen verarbeiten kann. Er heißt Grimand Elmore.\n\nIch habe das von Euch gefundene Eisen in eine Kiste gepackt. Bringt sie zu Grimand und erzählt ihm Eure Geschichte. Ich bin mir sicher, er wird jemandem, der auf einem Kreuzzug wie dem Euren ist, gefällig sein und Euch eine Waffe schmieden - eine Waffe, vor der sich sogar Morbent Teufel fürchten wird.", sourceObjective = "Bringt Grimand Elmore in Sturmwind die Kiste mit Lichtschmiedeblöcken.", sourceObjectiveStatus = "unverified-source-field" }
quests[323] = { id = 323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewährungsprobe", description = "Morbent Teufel ist ein Totenbeschwörer und ein Verbündeter der dunklen Reiter. Ich würde Euch ja erlauben, Euch der Macht von Morbent Teufel entgegenzustellen, aber ich werde Euch erst gegen dieses widerwärtige Scheusal kämpfen lassen, wenn ich Eure wahre Stärke kenne.\n\nIhr habt mir Eure Tapferkeit bereits bewiesen, aber wenn Ihr dem Totenbeschwörer wirklich trotzen wollt, dann beweist Euer Geschick zuerst an seinen Dienern.", sourceObjective = "Vernichtet 15 Skeletträuber, 3 Skelettheiler sowie 3 Skelettwärter und kehrt danach zu Sven zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[324] = { id = 324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorenen Blöcke", description = "Nachdem Ihr den einzelnen Lichtschmiedeblock aus der voll gelaufenen Kiste genommen habt, ist Euch klar, dass die Murlocs wohl den Rest gestohlen haben. Jagt die Murlocräuber in der Nähe des Wracks der 'Fischadler', um an das verloren gegangene lichtgeschmiedete Eisen zu kommen.", sourceObjective = "Sammelt 5 Lichtschmiedeblöcke und kehrt dann zu Glorin Stahlbraue im Sumpfland zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[325] = { id = 325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewaffnet und bereit", description = "Hier ist die Waffe gegen das Scheusal, von dem Ihr spracht. Ihr seid bestens vorbereitet, {name}. Viel Glück, und ich freue mich schon darauf, von Eurer Ruhmestat zu hören!", sourceObjective = "Bringt Morbents Bann zu Sven im Dämmerwald.", sourceObjectiveStatus = "unverified-source-field" }
quests[328] = { id = 328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der versteckte Schlüssel", description = "In den Berichten wird kein Wort über den Gefreiten Thorsen verloren, jedoch im Einband eines von Herods Geschäftsbüchern findet sich ein kleiner Messingschlüssel.\n\nUnd nach genauerem Studium seiner Notizen finden sich in den verschiedenen Dokumenten einige Verweise auf eine \"sichere Geldkassette\". Die Geldkassette befindet sich irgendwo innerhalb des Vorratslagers - des Höhlenkomplexes weiter hinten in Kurzens Truppenlager.\n\nWenn diese sichere Geldkassette gefunden wird und der kleine Messingschlüssel ihn öffnen kann, dann kann das Geheimnis um Thorsens Entdeckung vielleicht offenbart werden.", sourceObjective = "Verwendet den kleinen Messingschlüssel, um Buchmacher Herods Geldkassette zu öffnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[329] = { id = 329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der entlarvte Spion", description = "Unter den Wertgegenständen in der Geldkassette befindet sich eine schlammverschmierte, gekritzelte Notiz. Wenn sie auch kaum lesbar ist, so scheint es, als wäre es eine Abhandlung über den Gefreiten Thorsen. Sie beschreibt ausführlich seine Patrouillenrouten, mit wem er so spricht und wie er seine Zeit bei den Rebellen verbringt. Sie ist nur mit einem einzelnen Buchstaben unterschrieben: -M.\n\nDennoch muss, wer auch immer diese Notiz verfasst hat, stets in Thorsens Nähe gewesen sein. Wer auch immer diese Notiz verfasst hat, ist der Verräter im Rebellenlager.", sourceObjective = "Bringt die schlammverschmierte Notiz zu Leutnant Doren im Rebellenlager.", sourceObjectiveStatus = "unverified-source-field" }
quests[330] = { id = 330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patrouillen-Pläne", description = "Die Notiz, die Ihr mir gegeben habt, ist mit einem \"-M\" unterzeichnet... Ich weiß nicht, was das heißen könnte.\n\nAber... die Notiz sagt auch aus, dass diese Person letzte Woche die gleichen Patrouillenrouten wie Thorsen hatte. Also muss, wer auch immer mit Thorsen letzte Woche auf Patrouille war, der Verräter sein!\n\nGeht zu Korporal Sethmann. Er kümmert sich um die Patrouillenpläne und wird Euch sagen können, wer mit Thorsen unterwegs war.", sourceObjective = "Sprecht mit Korporal Sethmann.", sourceObjectiveStatus = "unverified-source-field" }
quests[331] = { id = 331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung bei Doren", description = "Wollte Leutnant Doren, dass Ihr Euch mit diesen Patrouillen-Informationen wieder bei ihm meldet?", sourceObjective = "Sprecht mit Leutnant Doren.", sourceObjectiveStatus = "unverified-source-field" }
quests[332] = { id = 332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weinladen-Werbung", description = "Wenn Ihr Euch mit irgendwem über Weine unterhaltet, werdet Ihr erfahren, dass wir Gallinas die besten Weine in ganz Sturmwind verkaufen. Wir sind auch nicht weit weg, immer noch innerhalb des Handelsdistrikts entlang der herrlichen Kanäle der Stadt.\n\nHier, nehmt dieses Flugblatt. Bringt es meiner Schwester Suzetta in unseren Laden, und Ihr erhaltet eine Gratisflasche unseres berühmten Dalaran Noir. Ihr werdet es nicht bereuen!", sourceObjective = "Geht zum Weingut Gallina und gebt Suzetta Gallina den Weingutschein, um eine kostenlose Flasche Wein zu erhalten.", progress = "Seid gegrüßt und fühlt Euch willkommen, edler Herr. Habt Ihr schon einmal einen unserer ausgezeichneten Weine versucht?", completion = "Ah, Ihr wart also bei Renato? Na dann, hier, bitte, werter Herr. Eine Flasche unseres außergewöhnlichen Dalaran Noir. Ihr werdet nirgendwo in Azeroth etwas Vergleichbares finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[333] = { id = 333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harlan braucht Nachschub", description = "Wir hatten hier in der letzten Zeit viel Betrieb. Es scheint so, als wollte wirklich jeder Rüstungen und robuste Kleidung kaufen. Als würden alle eine kalte, harte Jahreszeit erwarten... \n\nAber das sind alles Zukunftssorgen. Meine heutige Sorge ist eher, dass mir die gestrickten Kleidungsstücke ausgehen. Ich brauche eine weitere Fuhre von unserem Lieferanten.\n\nWenn Ihr diesen Auftrag zu Rema Schneider in die Schneiderei und Anpasserei am Kanal bringen könntet, wäre ich Euch sehr dankbar.", sourceObjective = "Geht zur Schneiderei und Anpasserei am Kanal und bringt Rema SchneiderHarlan BagleysStoffanforderung.", progress = "Ihr bringt Nachricht von Herrn Bagley?", completion = "Hier steht, dass Harlans Geschäfte florieren. Das sind gute Neuigkeiten, aber ich frage mich, wozu die Leute all diese Rüstungen brauchen. Ich habe nichts von einem Krieg gehört... gibt es da etwas, was uns die Adligen nicht erzählen?\n\nNun gut, danke, dass Ihr die Anfrage überbracht habt. Hier ist Eure Bezahlung, und ich werde dafür sorgen, dass Harlan seine Lieferung erhält.", sourceObjectiveStatus = "unverified-source-field" }
quests[334] = { id = 334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lieferung für Thurman", description = "Mein Sohn Thurman ist Lehrling beim Konfektionsgeschäft Larson im Magierviertel. Er hatte es heute etwas eilig und vergaß seine Schere und Nadeln. Ich weiß, <ein großer/eine große:c> {class} wie Ihr hat bestimmt wichtige Aufgaben zu erledigen, aber ohne sein Handwerkszeug kann er seine Lehrarbeiten nicht erledigen!\n\nBitte, {name}. Könnt Ihr meinem Sohn sein Nähkästchen vorbeibringen? Das Konfektionsgeschäft Larson ist einer von zwei Kleiderläden im Magierviertel - es ist das, das etwas weiter drin liegt, ganz in der Nähe des Magierturms.", sourceObjective = "Geht zum Konfektionsgeschäft Larson im Magierviertel von Sturmwind und gebt Thurman Schneider sein Nähkästchen.", progress = "Seid Ihr hier, um Kleidung zu kaufen?", completion = "Oh, verflucht! Ich dachte, wenn ich mein Nähzeug vergesse, muss ich heute nicht arbeiten. Ich schätze, jetzt muss ich den Larsons beim Nähen helfen... \n\nNa ja. Ich denke, das Vergnügen muss wohl noch etwas warten.", sourceObjectiveStatus = "unverified-source-field" }
quests[335] = { id = 335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein nobles Bräu", description = "Lord Wischock sorgt im Oberhaus ganz schön für Unruhe. Er wurde auf unseren kleinen Betrieb hier unten aufmerksam gemacht und propagiert jetzt eine genaue Untersuchung. Ich habe einen Plan, um Wischock... zu \"beschäftigen\"... aber ich benötige Eure Hilfe. \n\nEs gibt eine Blume, die in Stalvans Garten in den Außenbezirken von Dunkelhain wächst. Diese kleine weiße Blume ist als Tilloaträne bekannt. Ich werde außerdem eine Bisamwurzel brauchen, die man nur am Fuße des Wasserfalls tief unter dem Steinwerkdamm im Sumpfland findet.", sourceObjective = "Zardeth der Schwarzen Klaue möchte, dass Ihr ihm eine Tilloaträne aus Dunkelhain und eine Bisamwurzel aus dem Sumpfland bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[336] = { id = 336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein nobles Bräu", description = "Lord Wischock hat, wie alle Menschen, seine Schwächen. Bei seiner handelt es sich um eine Vorliebe für alkoholische Getränke. Seine Scheinheiligkeit ist verblüffend. Dieser spießige Trottel verbringt seine Tage damit zu versuchen, unsere kleine \"Taverne\" schließen zu lassen, während er seine Nächte im Obergeschoss zubringt und dabei Rechnungen anschreiben lässt, die er niemals bezahlt. Na, mal sehen, wie Wischock dieses besondere Gebräu schmeckt, das ich für ihn vorbereitet habe: Schwarzklauenbier. Es haut ziemlich rein, {name}.\n\nBringt es ihm und seht, wie es ihm schmeckt. Höchstwahrscheinlich treibt sich der alte Trottel in der Halle der Bittsteller herum.", sourceObjective = "Bringt Lord Wischock in der Halle der Bittsteller das Schwarzklauenbier.", sourceObjectiveStatus = "unverified-source-field" }
quests[337] = { id = 337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein altes Geschichtsbuch", description = "Obwohl der Einband dieses Buches von Kratzern überzogen und von Schmutz verkrustet ist, kann man auf dem Buchrücken noch immer die Worte \"Die Geschichte von Sturmwind\" lesen. Wenn man das Buch aufmacht, kann man das Siegel der Bibliothek von Sturmwind erkennen, das deutlich auf der ersten Seite prangt.\n\nEs sieht so aus, als hätte jemand dieses Buch ausgeliehen, aber nie zurückgegeben.", sourceObjective = "Bringt das Buch: Die Geschichte von Sturmwind in die Bibliothek von Sturmwind zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[338] = { id = 338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grünen Hügel des Schlingendorntals", description = "Meister Nesingwary wird furchtbar wütend sein, wenn er das herausfindet!\n\nEr vertraute mir das Manuskript für seinen Roman, Die Grünen Hügel des Schlingendorntals, zum Korrekturlesen an. Es lief auch alles glatt, aber dann wehte ein großer Windstoß durch das Lager und hat die Seiten überall verteilt.\n\nIch konnte die meisten Seiten wieder zusammensuchen, aber viele sind noch über den halben Dschungel verstreut. Sammelt die Seiten, mit denen man die vier Kapitel vervollständigen kann.\n\nIch werde Euch helfen, sie zu ordnen. Bringt mir die Kapitel zurück, wenn Ihr alle vier beisammen habt.", sourceObjective = "Sammelt die fehlenden Seiten des Manuskripts von Die Grünen Hügel des Schlingendorntals. Wenn alle vier Kapitel vollständig sind, bringt sie zu Barnil zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[339] = { id = 339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kapitel I", description = "Kapitel I war ziemlich fesselnd! Meister Nesingwary baut den Hintergrund der Geschichte auf und erwähnt seine Jagdgefährten, mich eingeschlossen! \n\nAber das tut gerade nichts zur Sache. Lasst mich mal sehen, welche Seiten noch fehlen. So wie es aussieht sind die Seiten 1, 4, 6 und 8 immer noch irgendwo da draußen im Dschungel!", sourceObjective = "Bringt Barnil Steinkrug die Seiten 1, 4, 6 und 8 von Nesingwarys Die Grünen Hügel des Schlingendorntals, um Kapitel I zu vervollständigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[340] = { id = 340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kapitel II", description = "Kapitel II war voll gestopft mit aufregenden Geschichten von der Panther- und Tigerjagd. Ich könnte mir dafür in den Hintern treten, dass ich die Seiten habe davonfliegen lassen. \n\nEs sieht aus, als hätte ich alle Seiten wiedergefunden, bis auf die Seiten 10, 11, 14 und 16.", sourceObjective = "Bringt Barnil Steinkrug die Seiten 10, 11, 14 und 16 von Nesingwarys Die Grünen Hügel des Schlingendorntals, um Kapitel II zu vervollständigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[341] = { id = 341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kapitel III", description = "Kapitel III gefiel mir am besten. Es erzählt von Sire Erlgadins und Lady Rouacks erstem Blattschuss mit einem Zwergengewehr. Und am Ende von Kapitel III, Mann, solche eine Spannung! \n\nWenn ich das richtig sehe, brauchen wir noch die Seiten 18, 20, 21 und 24, um das Kapitel fertig zu stellen. Diese Seiten sind irgendwo da draußen...", sourceObjective = "Bringt Barnil Steinkrug die Seiten 18, 20, 21 und 24 von Nesingwarys Die Grünen Hügel des Schlingendorntals, um Kapitel III zu vervollständigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[342] = { id = 342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kapitel IV", description = "Ah, Kapitel IV; Das große Finale! Und was für ein Ende es war! \n\nUns fehlen nur drei Seiten aus diesem Kapitel. Wir brauchen die Seiten 25, 26 und 27, um Kapitel IV wieder zusammenzusetzen.", sourceObjective = "Bringt Barnil Steinkrug die Seiten 25, 26 und 27 von Nesingwarys Die Grünen Hügel des Schlingendorntals, um Kapitel IV zu vervollständigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[343] = { id = 343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reden über Kraft", description = "Ich werde eine Rede über die Kraft des Geistes halten, und ich würde dazu gern einige Auszüge aus einem bestimmten Buch über Metallurgie zitieren - \"Belastbarkeit von Eisen\". Eine Abschrift dieses Buches dürfte sich in der Königlichen Bibliothek der Burg Sturmwind finden. Könnt Ihr es für mich holen? Wenn dem so ist, dann mögen die Segnungen des Lichts mit Euch sein!\n\nDie Königliche Bibliothek ist sehr groß, aber der oberste Bibliothekar, Milton Garbenbund, kennt jedes Regal, als wäre es sein eigenes Kind. Sprecht mit ihm, und er wird Euch das Buch holen.", sourceObjective = "Geht in die Königliche Bibliothek der Burg von Sturmwind und sprecht mit Milton Garbenbund. Er kann das Buch über Metallurgie für Euch finden, das Bruder Kristoff für seine Rede benötigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[344] = { id = 344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bruder Paxton", description = "Belastbarkeit von Eisen? Ja, ich kenne das Buch. Ziemlich gut, vor einigen Jahrzehnten von dem Zwergenminenarbeiter Margulf Blaggon geschrieben. Er verbrachte den Großteil seines Lebens tief in den Bergen von Khaz Modan, Erze schürfend. Kluger Kerl!\n\nAber wo war ich doch gleich? Ach ja, die Belastbarkeit von Eisen! Ich fürchte, das Buch wurde in die Abtei von Nordhain verlegt. Der Verwalter der Bibliothek der Abtei, Bruder Paxton, wollte eine Kopie des Buches für seine eigenen Regale anfertigen.\n\nDas war allerdings vor Monaten. Ich frage mich, warum er so lange dafür braucht...", sourceObjective = "Sprecht mit Bruder Paxton in der Abtei von Nordhain.", sourceObjectiveStatus = "unverified-source-field" }
quests[345] = { id = 345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tinten-Zutaten", description = "Ich will meine Abschrift von Belastbarkeit von Eisen schon länger fertig stellen, aber... \n\nNun, ich stelle für die Bücher, die ich abschreibe, meine Tinte selbst her, versteht Ihr? Es handelt sich um mein eigenes Rezept. Sie verläuft nicht, sie schmiert nicht und sie trocknet sehr schnell. Dummerweise trocknet sie ein wenig zu schnell! Meine letzte Portion ist ausgetrocknet, bevor ich die Abschrift beenden konnte, und ich hatte bisher keine Gelegenheit, mehr Tinte herzustellen!\n\nUm mehr herzustellen, benötige ich Rethbaneisenerz aus dem Rotkammgebirge. Großknecht Oslow in Seenhain ist mein üblicher Lieferant.", sourceObjective = "Sprecht mit Großknecht Oslow in Seenhain und fragt ihn nach Rethbaneisenerz.", sourceObjectiveStatus = "unverified-source-field" }
quests[346] = { id = 346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Kristoff", description = "Nachdem ich jetzt mit der Abschrift fertig bin, könnt Ihr das Original von Belastbarkeit von Eisen haben. Ich danke Euch für Eure Geduld, und wenn Ihr Milton seht, bitte sagt ihm, die lange Verzögerung täte mir leid.", sourceObjective = "Kehrt zu Bruder Kristoff auf den Kathedralenplatz zurück. Gebt ihm das Buch: \"Belastbarkeit von Eisen\".", sourceObjectiveStatus = "unverified-source-field" }
quests[347] = { id = 347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rethbanerz", description = "Rethbanerz wurde nach dem Mann benannt, der es als Erster entdeckt hat, Bart Rethban. Wenn es geschmolzen wird, ist es nicht so stark wie Eisen, aber sein Erz hat eine dunkle, glatte Farbe, die einige Schreiber in ihren Farbtinten verwenden. Man kann es in den Rethbanhöhlen nördlich von hier finden.\n\nWir haben normalerweise etwas davon auf Lager, aber wir sind zu sehr damit beschäftigt, uns auf Orcangriffe vorzubereiten, als dass wir welches sammeln könnten. Und nur so nebenbei... In den Rethbanhöhlen leben jetzt Rotkammgnolle und deren Zwangsarbeiter bauen das Erz selbst ab.\n\nWenn Ihr also welches benötigt, müsst Ihr es Euch selbst besorgen.", sourceObjective = "Sammelt 5 Fuhren Rethbanerz und bringt sie Bruder Paxton in der Bibliothek von Nordhain.", sourceObjectiveStatus = "unverified-source-field" }
quests[348] = { id = 348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlingendornfieber", description = "Krank... so... furchtbar k-k-krank... \n\n... habe mich mit Schlingendornfieber angesteckt... tödliches V-v-virus... \n\n... einziges Heilmittel... wäre... wäre es... das Herz von M-m-m-mokk dem Wilden zu essen... schwer zu fassendes, weißes Wildtier... \n\n... Hexendoktor Unbagwa... Einziger, der es b-b-beschwören kann...\n\n... sucht Unbagwa... versteckte Höhle am südlichen Kap...\n\n... schnell... sterbe... sterbe...", sourceObjective = "Sucht Hexendoktor Unbagwa und lasst ihn Mokk den Wilden beschwören. Bringt das Herz von Mokk zu Fin Fizrackett.", sourceObjectiveStatus = "unverified-source-field" }
quests[349] = { id = 349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlingendornfieber" }
quests[350] = { id = 350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf einen alten Freund verlassen", description = "Marzon würde ein Mitglied der Defias kontaktieren und er hat Verbindungen zu Lescovar... \n\nDa van Cleef und Thredd tot sind, wäre es schwierig, einen Richtspruch gegen Lescovar zu erwirken, denn Eure Beweise sind wertlos ohne deren Zeugnis. Und dabei wird noch nicht einmal die Tatsache berücksichtigt, dass Lescovar ja ein Adliger ist und viele Beziehungen hat. Das stellt ihn gewissermaßen über das Gesetz.\n\nWir werden weitere Hilfe benötigen. Ich tu das nur äußerst ungern, aber ich kenne jemanden, der uns helfen wird. Ihr findet Trias im Handelsdistrikt der Stadt.", sourceObjective = "Sprecht mit Elling Trias in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[351] = { id = 351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet OOX-17/TN!", description = "Ihr habt ein merkwürdiges Gerät aus Metall entdeckt, das die Form eines Eis hat. Als Ihr einen der Knöpfe berührt, erwacht das Ei zu Leben und verwandelt sich in eine Art Gnom-Roboter-Apparat! Aus dem Inneren des Roboteis erklingt eine rasselnde Stimme.\n\n\"Mein Name ist Glotz und mein Leitroboter ist verloren gegangen! Ich würde Euch belohnen, wenn Ihr ihn aufspürt! Bringt dem Roboter bitte diesen Signalgeber. Hervorragend, jetzt habe ich die Koordinaten für Euch berechnet! Er ist in der Nähe der Klaffenden Schlucht in Tanaris abgestürzt!\"", sourceObjective = "Bringt das Notsignal zum Leitroboter von Glotz.", progress = "Ihr habt anscheinend das Wrack eines... Roboterhuhns entdeckt... Aus dem Ei erklingt wieder die rasselnde Stimme:\n\n\"Ja, hervorragende Arbeit! Das ist tatsächlich mein Leitroboter, aber meine Sensoren zeigen an, dass er Starthilfe benötigt, bevor er zur Reparatur nach Beutebucht zurückfliegen kann. Bitte legt den Signalgeber in den Rover. Der Signalgeber wird den Rest übernehmen!\"", completion = "Ihr legt das Ei... das Notsignal... in das Huhn... den Leitroboter.\n\nAus dem Roboter ertönt ein Brummen und Surren, als er versucht aufzustehen. Nachdem der Roboter zum Leben erwacht ist, ertönt die Stimme von Glotz ein weiteres Mal, diesmal aus dem Inneren des Roboters:\n\n\"OOX-17/TN funktioniert endlich, aber es sind umfangreiche Reparaturen erforderlich! Er ist zu schwer, als dass Ihr ihn tragen könntet... aber ich glaube, ich habe eine Idee. Könntet Ihr noch etwas auf ihn aufpassen?\"", sourceObjectiveStatus = "unverified-source-field" }
quests[353] = { id = 353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmlanzes Lieferung", description = "Die Sturmlanzen sind ein geachteter Zwergenklan und bekannt für ihren feinen und kritischen Geschmack. Daher ist es nicht verwunderlich, dass Gringer Sturmlanze, ein Gebirgsjäger aus Eisenschmiede, mich beauftragte, ihm eine Waffe zu schmieden.\n\nDie Waffe ist fertig, aber... Gebirgsjäger Sturmlanze ist weit weg, am fernen Loch Modan. Wenn Ihr ohnehin vorhabt, nordwärts zu reisen, könntet Ihr ihm dieses Päckchen überbringen?\n\nMeine letzte Nachricht von Gebirgsjäger Sturmlanze besagte, dass er im nördlichen Wachturm des Loch Modan stationiert ist.", sourceObjective = "Bringt das Päckchen für Sturmlanze zu Gebirgsjäger Sturmlanze am Loch Modan.", progress = "Ihr seid den ganzen weiten Weg von Sturmwind gekommen? Ich habe gehört, es wird da unten in den Menschenlanden dank herumlaufender Briganten und Orcs etwas brenzlig. An einem solchen Ort kann ein {class} sich perfekt beweisen!", completion = "Aha! Grimand hat also endlich meine Axt fertiggestellt! Ich kann es kaum erwarten, sie an einigen Troggs und Kobolden auszuprobieren!\n\nVielen Dank, {name}. Ihr habt für diese Lieferung eine weite Strecke zurückgelegt. Hier habt Ihr ein paar Münzen für Eure Bemühungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[354] = { id = 354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesfälle in der Familie", description = "Die Familie Agamand war die wohlhabendste in Tirisfal. Ich habe früher in ihrer Mühle gearbeitet... vor der Seuche.\n\nAls die Geißel das erste Mal auftauchte, befestigten die Agamands ihre Heimstatt und überredeten ihre Angestellten zu bleiben und bei der Verteidigung zu helfen. Wir waren Narren, aber wir waren loyale Narren.\n\nDie Agamands haben uns in ihrem Stolz zum Untod verdammt. Und heute sind sie Diener der Geißel!\n\nDient den Verlassenen, indem Ihr die Agamands besiegt, die der Seuche zum Opfer fielen. Dient mir, indem Ihr mir ihre Überreste bringt.", sourceObjective = "Bringt Coleman Heller in Brill Gregors Überreste, Nissas Überreste und Thurmans Überreste.", sourceObjectiveStatus = "unverified-source-field" }
quests[355] = { id = 355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Sevren", description = "Ihr habt mir die Überreste der Agamands gegeben und meinen Rachedurst gestillt. Aber Agamands Mühlen sind eine Bedrohung für alle Verlassenen, nicht nur für mich.\n\nIch habe mit Magistrat Sevren über Eure Heldentaten gegen die Agamands geredet, und er wünscht, mit Euch zu sprechen.", sourceObjective = "Sprecht mit Magistrat Sevren in Brill.", sourceObjectiveStatus = "unverified-source-field" }
quests[356] = { id = 356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rear Guard Patrol" }
quests[357] = { id = 357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Identität des Lichs", description = "Es gibt einen Lich, der auf einer Insel im Blendwassersee im Norden haust. Obwohl er ein Verlassener mit freiem Willen ist, glaubt er, dass alle anderen Untoten Sklaven der Geißel sind, und hetzt seine Diener auf jeden, der sich ihm nähert.\n\nAber da er ein Verlassener ist, wird die Königin ihn haben wollen. Und wenn er in der Totenbeschwörung bewandert ist, dann wäre sein Wissen... recht nützlich für uns.\n\nUm etwas über seine Identität und sein Können herauszufinden, muss ich mir sein Zauberbuch ansehen. Stehlt Euch in sein Lager, verschafft es Euch und kehrt dann zu mir zurück.", sourceObjective = "Bringt das Zauberbuch des Lichs zu Bethor Eismacht in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[358] = { id = 358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grabräuber", description = "Die Massengräber südwestlich von Garrens Schlupfwinkel weiter im Norden wurden geschaffen, um der... eindrucksvollen... Anzahl Todesfälle gerecht zu werden, die Tirisfal erlitt, als die Seuche zum ersten Mal über uns kam. \n\nDen Toten in diesen Gräbern blieb der Untod bisher erspart, aber die Geißel schickt jetzt Moderfellgnolle, um die Leichen einzusammeln, um sie zur Verstärkung ihrer Armeen einzusetzen. Das können wir nicht zulassen!\n\nIhr habt zweierlei Aufgaben: Erschlagt die Moderfelle am Massengrab und in Garrens Schlupfwinkel und nehmt Euch von ihnen das Einbalsamierungssekret, das ihnen Leben verleiht.", sourceObjective = "Tötet Grabräuber der Moderfelle und Bastarde der Moderfelle. \n\nBringt Magistrat Sevren in Brill 8 Einbalsamierungssekrete.", sourceObjectiveStatus = "unverified-source-field" }
quests[359] = { id = 359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlassenen-Pflichten", description = "Ich brauche einen aktuellen Bericht von unserem Außenposten der Todeswache im Osten.\n\nIch muss wissen, ob mehr Streitkräfte der Geißel am Bollwerk vorbei und nach Tirisfal herein geschlichen sind. Unsere Wachsamkeit an der Grenze zu den Pestländern muss aufrechterhalten werden - wir können die Geißel hier nicht stärker Fuß fassen lassen!\n\nReist südwärts die Straße entlang und biegt an der Gabelung nach Osten zum Außenposten ab. Sprecht mit Todeswache Linnea. Sie hat die Informationen, die ich benötige.", sourceObjective = "Sprecht mit Todeswache Linnea.", sourceObjectiveStatus = "unverified-source-field" }
quests[360] = { id = 360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Magistrat", description = "Kehrt jetzt zu Magistrat Sevren mit den Informationen zurück, die ich euch gegeben habe. Er wird sie so schnell wie möglich haben wollen, also sputet Euch.\n\nUnd solltet Ihr unterwegs welche von der Geißel sehen, schaltet sie aus - wir können sie nicht unbehelligt durch unser Land spazieren lassen.", sourceObjective = "Kehrt zu Magistrat Sevren nach Brill zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[361] = { id = 361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Letter Undelivered" }
quests[362] = { id = 362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Spukmühlen", description = "Devlin Agamand war der jüngere von zwei Söhnen der Familie Agamand und im Leben hätten sie unterschiedlicher nicht sein können. Thurman war groß und sanft, während sein jüngerer Bruder schwach und scharfzüngig war.\n\nAls Agamands Mühlen der Seuche anheim fielen, war ich nicht überrascht zu hören, dass Devlin ihr schnell erlag. Sein verrücktes Gebrabbel kann man heute noch nahe der Straße hören, die zu Agamands Mühlen führt.\n\nIch sammle die Überreste der Agamands und ich möchte den armen Devlin. Findet ihn, vernichtet ihn und bringt mir seine Knochen.", sourceObjective = "Erschlagt Devlin Agamand und bringt Devlins Überreste zu Coleman Heller nach Brill.", sourceObjectiveStatus = "unverified-source-field" }
quests[363] = { id = 363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsanftes Erwachen", description = "Wurde auch Zeit, dass Ihr aufwacht. Wir wollten Euch gerade mit den anderen ins Feuer werfen, aber es sieht so aus, als hättet Ihr es geschafft.\n\nIch bin Mordo, der Verwalter der Gruft von Todesend. Und Ihr seid kein Sklave des Lichkönigs mehr.\n\nSprecht mit Schattenpriester Sarvis in der Kapelle am Fuße des Hügels, er wird Euch mehr über das erzählen, was Ihr wissen müsst.\n\nUm aus dieser Krypta zu kommen, steigt die Treppe zur Oberfläche hinauf. Folgt dann dem Weg hinunter zur Kapelle, um Sarvis zu finden.", sourceObjective = "Sprecht mit Schattenpriester Sarvis.", sourceObjectiveStatus = "unverified-source-field" }
quests[364] = { id = 364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mindless Ones" }
quests[365] = { id = 365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felder des Kummers", description = "Was haben wir denn hier? Ihr seht wie ein Neuling aus, {class}. Wenn Ihr darauf hofft, Euch der Dunklen Fürstin zu beweisen, dann müsst Ihr die Gebräuche der Verlassenen erlernen.\n\nIm Westen werdet Ihr einen Hof vorfinden. Menschen suchen das Land heim wie Schimmel eine verrottende Leiche. Und um es noch schlimmer zu machen, patrouilliert ganz in der Nähe der Scharlachrote Kreuzzug von seinem Turm aus. Erteilt diesem Abschaum eine Lektion und stehlt 10 ihrer kostbaren Kürbisse.\n\nSobald Ihr 10 beisammen habt, bringt sie zu Apotheker Johaan nach Brill.", sourceObjective = "Stehlt 10 Kürbisse vom Gehöft im Westen, direkt nördlich von Todesend und bringt sie zu Apotheker Johann nach Brill.", sourceObjectiveStatus = "unverified-source-field" }
quests[366] = { id = 366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückgabe des Buches", description = "Vor langer Zeit waren Gunther und ich, wie auch der jetzt der Geißel dienende Totenbeschwörer Thule Rabenklaue, Freunde und Schüler beim Kirin Tor, einer Magiergesellschaft in Dalaran.\n\nGunther und ich fielen beide der Seuche anheim, aber ich dachte, er wäre entweder tot geblieben oder für die Armee des Lichkönigs erweckt worden. Es tut gut zu wissen, dass er frei ist.\n\nWir müssen ihn für uns gewinnen. Ich habe einen Zauber auf dieses Buch gelegt, der ihm, sobald er ihn sieht, zeigen wird, dass ich ebenfalls frei vom Einfluss des Lichkönigs bin. Ich hoffe, dass er sich uns anschließt, wenn er das erfährt.", sourceObjective = "Bringt Gunthers Zauberbuch zu ihm auf die Gunthers Zufluchtsort genannte Insel zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[367] = { id = 367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine neue Seuche", description = "Fürstin Sylvanas hat sich an die königliche Apothekervereinigung gewandt. Die Dunkle Fürstin glaubt, dass unser Wissen, gepaart mit der neuentdeckten Magie, der Schlüssel zu Arthas' Untergang sein wird. Sie hat uns aufgefordert, eine neue Seuche zusammenzubrauen, eine Seuche, tödlicher als jedes Leiden in ganz Azeroth. Diese neue Krankheit wird Arthas' Armee der Geißel ins Verderben stürzen.\n\nMeine Studien zeigen, dass das Blut von Bestien der Schlüssel sein könnte. Bringt mir 5 Phiolen Schattenhundblut, damit ich meine Theorie ausprobieren kann.", sourceObjective = "Apotheker Johaan in der Stadt Brill möchte, dass Ihr 5 Phiolen Schattenhundblut sammelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[368] = { id = 368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Plague" }
quests[369] = { id = 369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine neue Seuche", description = "Während Ihr sammeln wart, habe ich einen alten Text in einem meiner Bücher entdeckt, der darauf hindeutet, dass eine uralte Seuche Tausende unschuldiger Opfer ausgelöscht hat. Man fand später heraus, dass der tödliche Erreger im Gift der Nachtweberspinnen erhalten blieb.\n\nBringt mir etwas Gift eines heimtückischen Nachtwebers, um dieses Experiment abzuschließen. Ich möchte sehen, ob das ansteckende Element des Giftes mit meinem neuen Gebräu harmoniert. Gerüchten zufolge leben die Spinnen im östlichen Tirisfal.", sourceObjective = "Apotheker Johaan in der Stadt Brill möchte, dass Ihr ihm 4 Proben vom Gift eines heimtückischen Nachtwebers bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[370] = { id = 370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Krieg mit dem Scharlachroten Kreuzzug", description = "Die strategischen Dokumente von Exekutor Arren enthalten alle Angaben, die wir brauchen, um die menschliche Plage aus den Ländern zu tilgen. Nach diesen Informationen hat der Scharlachrote Kreuzzug Hauptmann Perrine mit einer Brigade dem verfallenen Turm südwestlich von Brill zugeteilt.\n\nTötet Perrine sowie 3 Zeloten und 3 Missionare und erstattet mir dann Meldung.", sourceObjective = "Exekutor Zygand in Brill möchte, dass Ihr Hauptmann Perrine, 3 Scharlachrote Zeloten und 3 Scharlachrote Missionare tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[371] = { id = 371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg mit dem Scharlachroten Kreuzzug", description = "Wir befinden uns noch immer im Krieg, und der Scharlachrote Kreuzzug gewinnt an Stärke. Der Bericht, den mir Exekutor Arren schickte, zeigt auf, dass die Scharlachroten Kreuzzügler ihre Überfälle von dem verfallenen Turm im südöstlichen Tirisfal, nahe Balnirs Bauernhof, unter dem Kommando von Hauptmann Vachon ausgeführt haben.\n\nTötet Vachon, zusammen mit 5 Scharlachroten Ordensmitgliedern. Das sollte sich als vernichtender Schlag für den Kreuzzug erweisen!", sourceObjective = "Exekutor Zygand in Brill hat Euch damit beauftragt, Hauptmann Vachon und 5 Scharlachrote Ordensmitglieder zu erschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[372] = { id = 372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Krieg mit dem Scharlachroten Kreuzzug", description = "Scharlachrote Kreuzzügler haben vom verfallenen Turm im nördlichen Tirisfal, hinter Faols Ruheplatz, Überfälle ausgeführt. Nach den Informationen, die wir haben, führt ein unbarmherziger Kommandant mit Namen Hauptmann Melrache diese bösartige Truppe an.\n\nIch vertraue Euch eine besondere und gefahrvolle Mission an. Erschlagt Melrache und seine beiden Leibwachen im Namen der Dunklen Fürstin.", sourceObjective = "Exekutor Zygand in der Stadt Brill möchte, dass Ihr Hauptmann Melrache und seine beiden Leibwachen ermordet.", sourceObjectiveStatus = "unverified-source-field" }
quests[373] = { id = 373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der nie verschickte Brief", description = "Als Ihr Edwin van Cleef durchsucht, findet Ihr unter anderem einen nie verschickten Brief. Er ist adressiert an Baros Alexston, Stadtarchitekt von Sturmwind, Rathaus, Kathedralenplatz.\n\nEr scheint erst vor Kurzem geschrieben und versiegelt worden zu sein.", sourceObjective = "Bringt den Brief nach Sturmwind zum Stadtarchitekten Baros Alexston.", sourceObjectiveStatus = "unverified-source-field" }
quests[374] = { id = 374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesbeweis", description = "Exekutor Zygand sagt mir, dass Ihr Scharlachrote Kreuzzügler töten wart. In Tirisfal wimmelt es nur so von denen.\n\nVarimathras, Offizier der Dunklen Fürstin, kümmert sich persönlich darum, dass der Abschaum Azeroths, die Menschen, völlig ausgelöscht wird. Hier in Tirisfal stehen wir einer besonders lästigen Menschenbrut gegenüber: dem Scharlachroten Kreuzzug.\n\nBegebt Euch hinaus und führt eine Offensive gegen den Scharlachroten Kreuzzug, {class}. Bringt mir 10 Scharlachrote Insignienringe zum Beweis Eurer Loyalität Varimathras und der Dunklen Fürstin gegenüber.", sourceObjective = "Bringt Todeswache Burgess in Brill 10 Scharlachrote Insignienringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[375] = { id = 375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kälte des Todes", description = "Es ist jetzt so kalt. Die Seuche des Untodes kriecht durch meine Adern wie eine eisige Schlange. Ich werde bald den Hirnlosen Zustand erreichen. Doch auch ein besiegeltes Schicksal wird mich nicht davon abhalten, unserer Dunklen Fürstin zu dienen. Als der Ruf ertönte, nähte ich Leichensäcke für die gefallenen Soldaten von Sylvanas' mächtiger Armee.\n\nJetzt zittern meine Hände vor lauter Kälte. Wenn Ihr mir fünf Nachtsaugerpelze und etwas groben Faden bringen würdet, könnte ich mir eine Decke nähen. Helft mir, {name}, auf dass ich der Sache weiter dienen kann.", sourceObjective = "Bringt Gretchen Dedmar in Brill fünf Nachtsaugerpelze und etwas groben Faden.", sourceObjectiveStatus = "unverified-source-field" }
quests[376] = { id = 376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Damned" }
quests[377] = { id = 377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbrechen und Strafe", description = "Als wäre die Vernachlässigung der Einwohner des Dämmerwalds nicht schlimm genug, nein, die jüngste Entscheidung des Oberhauses, Dextren Ward in Sturmwind ins Gefängnis zu werfen, anstatt den Schurken - wie durch Lord Schwarzhaupts Urteil gefordert - zu enthaupten, ist ein Schlag ins Gesicht für den Rat von Dunkelhain.\n\nWard wurde dabei erwischt, wie er Leichen aus dem Friedhof an Morbent Teufel verkaufte, ein Verbrechen, auf das der Tod steht. Und dennoch fordert Sturmwind seine Gefangensetzung.\n\nErmordet Ward im Verlies von Sturmwind - bringt mir seine Hand - und ich werde Euch belohnen.", sourceObjective = "Ratsherr Mühlenstein von Dunkelhain will, dass Ihr ihm die Hand von Dextren Ward bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[378] = { id = 378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tief empfundener Zorn", description = "Ihr habt Eure Loyalität zu König Magni bewiesen, {class}. Und Euer Hass auf den Dunkeleisenabschaum ist genauso groß wie mein eigener.\n\nEs gibt da eine Aufgabe, die ich selbst beenden möchte, aber ich bin durch meine Ehre verpflichtet, bei Langzopf zu bleiben. Jedoch hat Roggo Informationen gesammelt, die belegen, dass Kam Tiefenzorn einer der Verschwörer beim Angriff auf den Thandolübergang war. Durch Tiefenzorns Pläne verlor Langzopf seine Sippe.\n\nTiefenzorn wird aus politischen Gründen im Verlies von Sturmwind festgehalten. Ich will ihn tot sehen, {name}. Für Langzopf! Bringt mir seinen Kopf!", sourceObjective = "Motley Garmason in Dun Modr verlangt Kam Tiefenzorns Kopf.", sourceObjectiveStatus = "unverified-source-field" }
quests[379] = { id = 379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durstlöscher", description = "Ihr möchtet eine Kraftquelle. Da kann ich Euch helfen. Wisst Ihr, was ich möchte? Ich möchte etwas zu Trinken! Bringt mir fünf Wasserbeutel eines Wüstenläufers und ich werde Euch die 4711-FTZ geben.\n\nUnd jetzt... ratet einmal, wo Ihr solche Wasserbeutel finden könnt! Warum geht Ihr nicht zu einem der Wüstenläufernomaden östlich von hier und bittet ihn um einen? Lasst mich wissen, ob das klappt.", sourceObjective = "Bringt Chefingenieur Bilgenritzel in Gadgetzan 5 Wasserbeutel eines Wüstenläufers.", sourceObjectiveStatus = "unverified-source-field" }
quests[380] = { id = 380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachtweber", description = "Eine unserer größten Schwierigkeiten besteht darin, die Rohstoffe zu besorgen, die wir zum Überleben brauchen. Gold war schon zu Hochzeiten der Macht der Allianz selten.\n\nEs gibt eine Goldmine im Nordwesten, die von Spinnen überrannt wurde. Wir brauchen das Gold dieser Mine, aber wir können es ja schlecht holen, während die Spinnen darin herumkrabbeln. Ich habe nicht viel Personal übrig für diese Aufgabe, also müssen wir sie Schritt für Schritt lösen.\n\nBegebt Euch dorthin und schaut mal, was Ihr für uns ausrichten könnt, {name}.", sourceObjective = "Exekutor Arren will, dass Ihr 8 junge Nachtweber und 5 Nachtweber tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[381] = { id = 381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Scharlachrote Kreuzzug", description = "Ihr werdet erfreut sein zu hören, dass wir anscheinend Fortschritte in der Mine machen. Der Dank dafür gebührt zu einem nicht unerheblichen Maß Euren Bemühungen. Nun können wir uns anderen Belangen zuwenden.\n\nMeine Späher haben berichtet, dass eine Abteilung des Scharlachroten Kreuzzugs südöstlich von hier ein Lager errichtet. Der Scharlachrote Kreuzzug ist eine verabscheuungswürdige Organisation, die uns jagt, und sie wird nicht ruhen, ehe nicht alle Untoten - ganz gleich, ob Teil der Geißel des Lichkönigs oder nicht - vernichtet sind. Wir müssen ihnen zuvorkommen!\n\nSeid vorsichtig, denn der unheilige Eifer dieser Leute macht sie zu gefährlichen Gegnern.", sourceObjective = "Bringt Exekutor Arren insgesamt 12 Scharlachrote Armbinden von Scharlachroten Konvertiten und Scharlachroten Initianden.", sourceObjectiveStatus = "unverified-source-field" }
quests[382] = { id = 382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Rote Bote", description = "Berichte meiner Vorgesetzten in Brill weisen darauf hin, dass ein Agent des Scharlachroten Kreuzzugs vom Scharlachroten Kloster hierher nach Todesend entsendet wurde. Nach diesen Berichten führt dieser Bote wichtige Informationen mit sich. Ich kann nicht mit Einzelheiten dienen, aber was auch immer es ist, wir müssen es haben!\n\nIhr seid die qualifizierteste Person, die ich darauf ansetzen kann, {name}. Findet diesen Boten und bringt mir alle Informationen, die er bei sich trägt.", sourceObjective = "Tötet Meven Korgal, den Boten, im Lager der Kreuzzügler und kehrt danach mit allen Informationen, die Ihr findet, zu Exekutor Arren zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[383] = { id = 383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entscheidende Informationen", description = "Das muss zu meinem Vorgesetzten, Exekutor Zygand, nach Brill gebracht werden. Mit diesen Informationen können wir dem Scharlachroten Kreuzzug einen entscheidenden Schlag versetzen. Eure Dienste waren hier in Todesend nützlich, aber ich benötige jemanden, der dies zu Zygand bringt, und ich denke, er wird angemessenere Arbeiten für Euch finden. \n\nNehmt die Straße nach Norden, hinaus aus Todesend. Kurz nachdem Ihr nach Tirisfal hineinkommt, trefft Ihr auf eine Kreuzung. Nehmt die Abzweigung nach Osten und behaltet diese Richtung dann bei. Ihr werdet unterwegs am Verlassenen Anwesen vorbeikommen.", sourceObjective = "Bringt die Dokumente des Scharlachroten Kreuzzugs zu Exekutor Zygand nach Brill.", sourceObjectiveStatus = "unverified-source-field" }
quests[384] = { id = 384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eberrippchen in Biersauce", description = "Meine Tavernengäste mögen nichts so sehr wie meine Eberrippchen in Biersauce. Das einzige Problem dabei ist, dass der ortsansässige Fallensteller, der mich bisher mit den Zutaten versorgt hat, in die Armee des Königs eingetreten ist, um im Krieg an der Allianzfront zu helfen. \n\nVielleicht könnt Ihr mir helfen? Wenn Ihr mir ein paar Klippeneberrippchen bringt und ein Rhapsodiemalz von der Taverne hier besorgt, bekommt Ihr das Familienrezept für meine berühmten Eberrippchen in Biersauce und nicht zu vergessen natürlich eine Kostprobe! Das Geheimnis liegt im Malz!", sourceObjective = "Ragnar Donnerbräu in Kharanos benötigt 4 Klippeneberrippchen und einen Krug Rhapsodiemalz.", progress = "Ich werde diese Klippeneberrippchen und einen Krug Rhapsodiemalz benötigen, {name}.", completion = "Das Malzbier ist gebraut, die Wildschweine sind abgestochen\nDoch bevor das letzte Wort gesprochen\nWerden wir um dieses leckere Essen\nDer Eberrippchen in Biersauce\nUns erst im Kampfe messen!", sourceObjectiveStatus = "unverified-source-field" }
quests[385] = { id = 385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krokiliskenjagd", description = "So manchen Jäger zieht es an den Loch Modan, um unsere berühmten Krokis zu erlegen. Irgendein Händler sucht immer Krokiliskenhäute für seine Kleidungsstücke oder Rüstungen und es gibt auch einige Leute, denen ihr Fleisch mundet.\n\nWir handeln ein wenig damit, aber nicht wirklich viel, denn die Krokilisken sind wild und haben sich auf den Inseln im Loch verschanzt. Aber ich will Euch nicht davon abbringen, denn es ist ein unvergessliches Erlebnis, mit den Kiefern der Bestien zu ringen.\n\nAch ja, das eine Mal damals...", sourceObjective = "Besorgt 5 Stücke Krokiliskenfleisch und 6 Krokiliskenhäute für Marek Eisenherz in der Jagdhütte der Weltenwanderer.", sourceObjectiveStatus = "unverified-source-field" }
quests[386] = { id = 386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbrechen lohnt sich nicht", description = "Targorr der Schreckliche diente als oberster Exekutor unter Gath'llzogg. Er ging grausam vor, selbst nach den Standards der dreckigen Orcs. Menschen, die tapfer gekämpft hatten, um das Königreich zu verteidigen, wurden nur zu seiner Belustigung gefoltert. Heute wird er im Verlies von Sturmwind gefangen gehalten und wurde zum Tode verurteilt. Dennoch stimmt irgendetwas nicht. Einer dieser bürokratischen Adeligen hat seine Exekution ausgesetzt. Ich bin mir sicher, hier wird eine Schandtat geplant.\n\nMacht Targorr dem Schrecklichen ein Ende, {name}. Reist zum Verlies und enthauptet ihn, bevor man uns überlistet.", sourceObjective = "Bringt Wache Berton in Seenhain den Kopf von Targorr dem Schrecklichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[387] = { id = 387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Niederschlagung des Aufstandes", description = "Der Aufstand muss niedergeschlagen werden! Ich brauche Eure Hilfe. Wenn jemand mitbekommt, dass das Gefängnis überrannt wurde, verliere ich meinen Job! Solch übles Spiel habe ich noch nie erlebt. Aber was jetzt zählt ist, die Gefangenen zur Sicherheit Sturmwinds niederzuringen.\n\nDie Strafe für Auflehnung lautet Tod. Tötet einige dieser Abweichler! Das sollte die Angelegenheit wieder unter Kontrolle bringen.", sourceObjective = "Aufseher Thelwasser aus Sturmwind will, dass Ihr im Verlies 10 Gefangene, 8 Sträflinge und 8 Aufrührer tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[388] = { id = 388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Farbe von Blut", description = "Verbitterung fließt wie ein kalter Fluss durch meine Adern. Mein Enkel, Mac, war so ein guter Junge. Gerade mal 14 Jahre alt. Als die Armee an die Front geschickt wurde, griff Mac zu den Waffen, um die Stadt zu verteidigen. Er war eine Wache im Verlies, wo diese elenden Defias eingesperrt sind. Mac wies ein paar der Gefangenen dafür zurecht, dass sie ihre Wolldecken zerrissen, um Schals daraus zu machen, die ein Symbol ihrer Bande darstellen. Dafür wurde Mac hinterhältig erstochen.\n\nIch will Rache. Bringt mir 10 ihrer kostbaren Wollkopftücher. Sie haben die Farbe von Blut.", sourceObjective = "Nikova Raskol von Sturmwind will, dass Ihr 10 rote Wollkopftücher für sie sammelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[389] = { id = 389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bazil Thredd", description = "Van Cleef und ich waren beide Mitglieder der Steinmetzgilde. Unser Hauptprojekt war der Wiederaufbau Sturmwinds nach dem Krieg.\n\nAls wir unsere Aufgabe erfüllt hatten, wurden wir betrogen. Die Adligen verweigerten uns die Bezahlung für unsere Arbeit. Einigen der älteren Steinmetze wurden Posten in der Regierung angeboten, aber van Cleef lehnte aus Loyalität zu den übrigen Steinmetzen ab. Er führte eine Revolte an und verließ, Rache schwörend, die Stadt.\n\nSein Helfer, Bazil Thredd, könnte vielleicht mehr über van Cleefs Pläne wissen. Er wird im Verlies gefangen gehalten.", sourceObjective = "Sprecht mit Aufseher Thelwasser im Verlies.", sourceObjectiveStatus = "unverified-source-field" }
quests[391] = { id = 391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstand im Verlies", description = "Lasst uns eine Sache klarstellen, {name}: Ich traue Euch nicht. Aber wie die Sache im Moment aussieht, werdet Ihr ohnehin keinen Unterschied machen.\n\nAlso wird das folgendermaßen ablaufen: Geht da runter und redet mit Thredd. Wenn Ihr wirklich auf unserer Seite seid, dann eliminiert ihn und bringt mir seinen Kopf, wenn Ihr fertig seid. Und falls sich herausstellt, dass Ihr auf seiner Seite seid und nicht herauskommt... werdet Ihr zusammen mit dem Rest dieser Würmer sterben, wenn wir Euch finden.", sourceObjective = "Tötet Bazil Thredd und bringt seinen Kopf mit zurück zu Aufseher Thelwasser im Verlies.", sourceObjectiveStatus = "unverified-source-field" }
quests[392] = { id = 392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der seltsame Besucher", description = "In den ersten Jahren von Thredds Gefangenschaft bekam er niemals Besuch. Ich ging davon aus, dass er für die Bruderschaft keinen Nutzen mehr hatte und sie ihn daher fallen ließ.\n\nAber vor einigen Monaten hat sich das alles geändert; er bekam regelmäßig Besuch... einmal, manchmal sogar zweimal pro Woche. Es war ein seltsamer Mann, so ein ruhiger Typ. Ich hatte da so meinen Verdacht, aber alle seine Papiere waren in Ordnung.\n\nLaut seinen Dokumenten war sein Name Maelik; hier habt Ihr seine Beschreibung. Ich glaube nicht, dass er noch einmal kommen wird, um Thredd zu besuchen.", sourceObjective = "Bringt die versiegelte Beschreibung von Thredds Besucher nach Sturmwind zu Baros Alexston.", sourceObjectiveStatus = "unverified-source-field" }
quests[393] = { id = 393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatten der Vergangenheit", description = "Ich habe wirklich keine Ahnung, {name}. Aber es gibt da jemand anderen, der Euch vielleicht helfen kann, und wie es der Zufall so will, schuldet dieser Jemand mir einen Gefallen, weil... egal, das brauchen wir jetzt nicht zu vertiefen. Ihr könnt Meister Mathias Shaw vom SI:7 in der Kaserne in der Altstadt finden. Shaw hat seine Finger in den meisten zwielichtigen oder heimlichen Geschäften der Stadt.\n\nWenn also jemand etwas weiß, dann er.", sourceObjective = "Bringt die versiegelte Beschreibung von Thredds Besucher nach Sturmwind zu Meister Mathias Shaw.", sourceObjectiveStatus = "unverified-source-field" }
quests[394] = { id = 394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kopf des Ganzen", description = "Sucht Shaw in der Altstadt. Teilt ihm mit, dass Ihr Euch um die Bedrohung durch Lescovar gekümmert habt, und berichtet ihm von Eurer Beteiligung an den Plänen des Lords gegen die Stadt. Ich bin sicher, er wird stolz sein, einen weiteren Helden unter den Bürgern Sturmwinds zu haben.\n\nEr wird Euch ganz bestimmt zu einem Treffen mit dem Prinzen oder einem anderen Adligen schicken. Lasst Euch das nicht zu Kopfe steigen, {name}. Die Adligen können noch so sehr glauben, dass sie die Stadt beherrschen, aber einige Dinge bleiben für die im Dunklen.", sourceObjective = "Sprecht mit Mathias Shaw in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[395] = { id = 395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende der Bruderschaft", description = "Ach, das hätte ich fast vergessen. Alexston kam vorbei, als Ihr unterwegs wart, und wünschte mit Euch zu sprechen. Zweifellos möchte er den Adligen über die Ränkespiele der Defiasbruderschaft berichten.\n\nEin kleiner Rat, {name}: Sollte Euch jemand fragen, würde ich zwar alle Details offen legen, aber dabei nicht erwähnen, dass es Eure Hand war, die Lescovar erschlug. Vertraut mir. Ich... kenne mich aus... mit solchen Dingen.\n\nUnd was Trias angeht, nun, sprecht mit niemandem über ihn... niemals... wenn Ihr es vermeiden könnt.", sourceObjective = "Sprecht mit Baros Alexston in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[396] = { id = 396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Audienz beim König", description = "Ich habe einen Bericht an den König vorbereitet. Und Ihr sollt sein Überbringer sein, zusammen mit einer Auflistung Eurer Ergebnisse. Macht Euch keine Sorgen, er wird Euch zweifellos für die Erfüllung Eurer Pflicht gegenüber den Leuten von Sturmwind loben.\n\nEure Audienz findet in Kürze statt, also solltet Ihr Euch besser beeilen, denn es ist schon ein Stück Weges bis zur Burg Sturmwind.", sourceObjective = "Liefert Baros AlexstonsBericht über die Bruderschaft der Defias bei König Varian Wrynn in der Burg Sturmwind ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[397] = { id = 397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr habt uns gut gedient", description = "Wie ich höre, hat Lord Wischock sein Getränk genossen. \n\nIhr habt uns gut gedient, {name}. Die Hexenmeister von Sturmwind werden nun, dank Euch, ohne Störung ihrem Tagewerk nachgehen können. Ich habe ein besonderes Geschenk vorbereitet, um Euch für Eure Mühen zu entlohnen. Sprecht mit meinem Diener, Zggi, um Eure Belohnung zu erhalten.", sourceObjective = "Sprecht mit Zggi, dem Diener von Zardeth der Schwarzen Klaue, um Eure Belohnung zu erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[398] = { id = 398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Madenauge", description = "Gesucht: Madenauge!\n\nDie selbst für einen Gnoll außerordentlich niederträchtige Kreatur wurde für ihre Verbrechen an den Verlassenen zum Tode verurteilt. Dieser verabscheuungswürdige Verbrecher hat Leichen für die Armee des Lichkönigs gestohlen. Madenauge wurde zuletzt gesehen, als er die Gegend nahe Garrens Schlupfwinkel nördlich von Brill plünderte.\n\nDie Stadt Brill bietet hiermit eine Belohnung für die fähige Seele, die die Exekution durchführt. Zeigt Exekutor Zygand die Tatze des Verbrechers, wenn die Tat getan ist.\n\nGnade ist etwas für die Schwachen.", sourceObjective = "Tötet Madenauge und kehrt dann mit seiner Tatze zu Exekutor Zygand nach Brill zurück, um eine Belohnung zu erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[399] = { id = 399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein bescheidener Anfang", description = "Es kommt mir so vor, als wäre es ewig her, dass ich als Junge in Westfall auf dem Hof gearbeitet habe. Man sagt ja, man kann niemals in der Zeit zurückgehen, und es stimmt wohl. In meinem Fall trifft das sogar gleich doppelt zu, denn das Heim meiner Familie wurde niedergebrannt und von Dieben besetzt.\n\nIch habe mit meinem Vater über den Verbleib einiger meiner Habseligkeiten gesprochen, darunter mein erster Kompass. Er konnte sie nicht retten. Allerdings meint er auch, dass sie auf dem Hof versteckt sein müssten.\n\nIhr findet Alexstons Bauernhof westlich der Späherkuppe. Könntet Ihr vielleicht dorthin gehen und mir meinen Kompass wiederbringen?", sourceObjective = "Begebt Euch zu Baros Alexstons Haus in Westfall und sucht nach seinem Kompass. Übergebt ihm diesen dann am Kathedralenplatz von Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[400] = { id = 400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werkzeuge für Stahlrost", description = "Beldin Stahlrost ist der Besitzer der örtlichen Maschinenschlosserei, und er ist der beste Monteur von Belagerungsmaschinen, den es gibt! Allerdings geht er nicht sehr gnädig mit seinen Werkzeugen um. Ich schwöre Euch, er macht bald mehr Bogenlichtschraubenschlüssel kaputt, als wir ihm liefern können!\n\nWir haben gerade seine letzte Werkzeugbestellung fertig. Wenn Ihr sie ihm anliefert, wird er sich sicherlich erkenntlich zeigen.\n\nSein Geschäft, Stahlrosts Depot, liegt etwas nordöstlich von Kharanos. Und nebenbei, es handelt sich dort um einen örtlichen Treffpunkt für die Veteranen unter den Piloten der Belagerungsmaschinen, also hört Euch ruhig ein wenig um, während Ihr dort seid.", sourceObjective = "Liefert Beldin Stahlrost seine Werkzeuge.", sourceObjectiveStatus = "unverified-source-field" }
quests[401] = { id = 401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wartet, bis Sirra fertig ist", description = "Ich bin fast mit der Übersetzung dieser Notiz fertig. Wenn Ihr in ein paar Minuten wiederkommt, dürfte ich fertig sein.", sourceObjective = "Wartet einen Moment und sprecht dann erneut mit Sirra Von'Indi.", sourceObjectiveStatus = "unverified-source-field" }
quests[402] = { id = 402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sirra ist beschäftigt", description = "Tut mir leid, aber bei dem Zustand, in dem die Stadt sich derzeit befindet, gibt es leider andere Dinge, die meine Aufmerksamkeit erfordern. Vielleicht kann ich diese Übersetzung später beenden, falls wir überleben.", sourceObjective = "Schaut später noch einmal nach, ob Sirra immer noch beschäftigt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[403] = { id = 403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das bewachte Fass mit Donnerbier" }
quests[404] = { id = 404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Putrid Task" }
quests[405] = { id = 405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der abtrünnige Lich", description = "Bethor Eismacht, ein hochrangiger und mächtiger Magier aus Unterstadt im Süden, befiehlt mir, ihm einen Agenten zu schicken, der seinen Wert gegen die Geißel bereits bewiesen hat. Ihr, {name}, werdet dieser Agent sein.\n\nZeigt Bethor diese Befehle. Er wird Euch daraufhin über Eure Mission aufklären. Ich kenne keine Details, aber es hat etwas damit zu tun, einen eigenwilligen Lich zu rekrutieren. Und es wird gefährlich sein.\n\nAlso macht Euch bereit, {class}. Ihr dürft nicht scheitern.\n\nIhr dürftet Bethor im Magieviertel von Unterstadt finden.", sourceObjective = "Zeigt Bethor Eismacht in Unterstadt Sevrens Befehle.", sourceObjectiveStatus = "unverified-source-field" }
quests[407] = { id = 407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felder des Kummers", description = "Harmlose Kürbisse, oder? Zumindest sehen sie so aus. Wenn wir Arthas' Vormarsch im Norden und die menschliche Plage im Süden stoppen wollen, müssen wir alle Möglichkeiten unseres untoten Daseins nutzen.\n\nMit etwas Einfallsreichtum wird sogar aus einem einfachen Kürbis ein Agent für unsere Dunkle Fürstin. Dieser Kürbis wird sich, wenn nach meiner jüngsten Formel behandelt, als eine besondere Leckerei erweisen.\n\nEs wurde schon wieder ein Scharlachroter Zelot gefangen genommen, der derzeit im Keller der Taverne Zur Galgenschlinge gefangen gehalten wird. Bringt dem Trottel diesen Kürbis.", sourceObjective = "Bringt den getränkten Kürbis zum gefangenen Scharlachroten Zeloten, der im Keller der Taverne Zur Galgenschlinge gefangen gehalten wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[408] = { id = 408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Familiengruft", description = "Die Gegend um Agamands Mühlen hat sich zu einem Außenposten der Geißel entwickelt. Am stärksten sind sie in der Gruft der Familie Agamand, wo ihr örtlicher militärischer Anführer, ein Skelett namens Hauptmann Dargol, sein Hauptquartier hat. Er hat die Vorfahren der Agamands durch Nekromantie wiedererweckt und hat vor, sie gegen uns einzusetzen.\n\nDies darf nicht geschehen, und Ihr müsst es verhindern. Reist zur Gruft der Familie Agamand und besiegt die erweckten Vorfahren der Agamands.\n\nUnd bringt mir den Schädel von Hauptmann Dargol.", sourceObjective = "Tötet 8 Klagende Vorfahren und 8 Faulende Vorfahren.\n\nTötet Hauptmann Dargol und bringt seinen Schädel zu Magistrat Sevren nach Brill.", sourceObjectiveStatus = "unverified-source-field" }
quests[409] = { id = 409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treuebeweis", description = "Ihr behauptet, Ihr wärt nicht dem Willen des Lichkönigs unterworfen, und die Verzauberung, die Bethor auf mein Buch legte, untermauert dies. Aber bevor ich Euch glaube, muss ich den Beweis haben, dass Ihr der Geißel feindlich gegenübersteht.\n\nEs gibt einen alten, blutigen Altar kurz vor der Südküste dieser Insel. Er wird von einer mächtigen Dienerin der Geißel, Lillith Nefara, verwendet.\n\nNehmt eine Kerze des Heranlockens aus dieser Kiste hier. Entzündet sie auf dem Altar, und Lillith wird erwachen. Vernichtet Lillith, und ich werde Euch glauben, dass Ihr ein Gegner des Lichkönigs seid.", sourceObjective = "Beschafft Euch eine Kerze des Heranlockens.\n\nBeschwört Lillith Nefara und tötet sie.\n\nKehrt zu Gunther auf seiner Insel zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[410] = { id = 410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlummernde Schatten" }
quests[411] = { id = 411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr des abtrünnigen Lichs", description = "Bringt meinem alten Kameraden Bethor diesen Netheredelstein. Er wird uns ermöglichen, miteinander zu kommunizieren... und ich habe ihm eine Menge zu erzählen.", sourceObjective = "Bringt den Netheredelstein zu Bethor Eismacht nach Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[412] = { id = 412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation Rekombobulationsgerät", description = "Ich sollte nach Gnomeregan zurückkehren und meine Forschungen für eine Heilung der verstrahlten Gnome vorantreiben.\n\nIch bin aber in Kharanos geblieben, weil es meine Heimatstadt ist und ich dabei helfen wollte, sie vor den Übergriffen der Frostmähnen zu schützen. Ich arbeite daran, die Dampfpanzer zu reparieren und in Ordnung zu halten.\n\nFragt mich nicht warum, aber die Strauchdiebe der Frostmähnen interessieren sich sehr für die gyromechanischen Getriebeteile, die ich für meine Reparaturen brauche. Sie treiben sich an der Frontlinie der Frostmähnen südöstlich der Stadt herum. Würdet Ihr mir dabei helfen, die Getriebeteile zurückzubekommen?", sourceObjective = "Bringt Razzle Flinkspross 8 gyromechanische Getriebeteile.", progress = "Die Piloten können es kaum erwarten, wieder in ihre Dampfpanzer einzusteigen und das Schlachtfeld zurückzuerobern. Enttäuschen wir sie nicht.", completion = "Diese gyromechanischen Getriebeteile sind perfekt! Die zwei Panzerpiloten sind schon so gut wie auf dem Weg zurück in die Schlacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[413] = { id = 413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schimmerstarkbier", description = "Ich möchte, dass mein Bruder Wellart mein neues Schimmerstarkbier ausprobiert. Er ist Gebirgsjäger und im südlichen Wachturm stationiert, einem von zwei Türmen an der Grenze zum Loch Modan.\n\nEr mag vielleicht kein Bierbrauer sein wie der Rest von uns Gerstenbräus, aber er trinkt gern mal einen, und ich bin mir sicher, er wird dies hier mögen.\n\nKönnt Ihr ihm dieses Fass Schimmerstarkbier für mich bringen?", sourceObjective = "Bringt das Fass mit Schimmerstarkbier zu Gebirgsjäger Gerstenbräu.", sourceObjectiveStatus = "unverified-source-field" }
quests[414] = { id = 414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Starkbier für Kadrell", description = "Ich habe inzwischen mehr von diesem Schimmerstarkbier getrunken, das mein Bruder gebraut hat - das ist großartiges Zeug! Ein Gebirgsjägerkumpel von mir muss das mal probieren. Er heißt Kadrell und patrouilliert normalerweise entlang der Straße durch Thelsamar beim Loch Modan.\n\nUm nach Thelsamar zu gelangen, müsst Ihr südostwärts durch den Tunnel gehen und dann nach Nordosten abbiegen, wenn der Pfad auf eine Straße trifft. Dieser Straße folgt Ihr direkt bis nach Thelsamar.\n\nGebt Gebirgsjäger Kadrell dieses Fässlein Schimmerstarkbier und schaut mal, was er davon hält!", sourceObjective = "Bringt das Fässlein mit Schimmerstarkbier zu Gebirgsjäger Kadrell.", sourceObjectiveStatus = "unverified-source-field" }
quests[415] = { id = 415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rejolds neues Gebräu", description = "Rejold Gerstenbräu aus Bräuhall hat nach Euch gefragt.\n\nEr möchte mit Euch über ein neues Getränk reden, das er gebraut hat... er sagte etwas davon, dass Ihr ihm vielleicht dabei helfen könntet. Vielleicht wollt Ihr also wieder nach Bräuhall zurückkehren, um herauszufinden, worum es geht.\n\nEs könnte etwas Freibier für Euch drin sein...", sourceObjective = "Sprecht mit Rejold Gerstenbräu.", sourceObjectiveStatus = "unverified-source-field" }
quests[416] = { id = 416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rattenfang", description = "Wir haben hier in der Gegend ein Problem mit einer echten Plage. Kobolde der Tunnelratten sind ins Vorgebirge eingedrungen, haben dort ihre Baue eingerichtet und verdrecken unser Land mit ihrem Abfall!\n\nWir wollen, dass sie ausgelöscht werden. Jagt sie, bringt mir ihre Ohren und kassiert das Kopfgeld.\n\nIhr findet die größte Ansammlung von Kobolden der Tunnelratten im Osten in und um die Silberbachmine herum.", sourceObjective = "Bringt Gebirgsjäger Sturmlanze an der Station Algaz 8 Tunnelrattenohren.", sourceObjectiveStatus = "unverified-source-field" }
quests[417] = { id = 417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilotenrache", description = "Hangflug schrieb in sein Tagebuch, dass er von Marterklaue, einem \"gewaltigen Eisklauenbären\", angegriffen wurde. Er hat die Bestie verjagt, aber nicht, ohne vorher übel zugerichtet zu werden.\n\nWenn man sich den Zustand von Hangflugs Leiche so ansieht, muss Marterklaue später wiedergekommen sein und ihn getötet haben.\n\nJedenfalls schrieb Hangflug in sein Tagebuch einen letzten Wunsch:\n\nRache an Marterklaue.", sourceObjective = "Tötet Marterklaue.\n\nBringt Pilot Hammerfuß am Südtoraußenposten die räudige Klaue des Bären und Hangflugs Tagebuch.", sourceObjectiveStatus = "unverified-source-field" }
quests[418] = { id = 418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutwurst aus Thelsamar", description = "Es gibt hier in Thelsamar immer genug Mäuler zu stopfen, mit all den Kindern, die ein und aus gehen, und den Arbeitern von den Ausgrabungsstätten, die nach einem arbeitsreichen Tag hereinkommen. Wir sind berühmt für unsere Blutwurst, Ihr habt sie nicht zufällig schon einmal probiert?\n\nNein? Nun, hierzulande muss man für seine Mahlzeiten arbeiten, und glaubt nur nicht, dass Ihr eine Ausnahme seid, nur weil Ihr <ein toller/eine tolle:c> {class} seid.\n\nIch brauche Bärenfleisch, Ebergedärme für die Pelle und Spinnensekret als Würzmittel. Bringt mir das alles und überlasst dann Vidra das Kochen!", sourceObjective = "Bringt Vidra Ofenglut in Thelsamar 8 Stück Bärenfleisch.", sourceObjectiveStatus = "unverified-source-field" }
quests[419] = { id = 419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Pilot", description = "Mein Freund Mori Hangflug, ebenfalls ein Pilot der Belagerungsmaschinen, hat sich in den Hügeln verirrt. Wir haben nach einem seltenen Erz gesucht, das man für hochwertiges Sprengpulver benötigt, und während unserer Suche hat er seine Maschine einen steilen Hügel hinaufgefahren und sie dabei kaputt gemacht!\n\nImmer noch überzeugt davon, dass es in diesen Bergen Erz gibt, hat er mich beauftragt, unsere Maschinen zu bewachen, während er zu Fuß weitersuchen wollte.\n\nDas ist jetzt mehrere Tage her, und ich habe des Nachts nördlich vom Helmsbettsee und westliches des Tunnels das Knurren von Raubtieren gehört. Mori ist ein zäher Bursche, aber ich mache mir Sorgen.\n\nBitte, {name}. Sucht ihn.", sourceObjective = "Pilot Hammerfuß am Südtoraußenposten möchte, dass Ihr den Piloten Hügelflug findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[420] = { id = 420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Senirs Beobachtungen", description = "Die Troggs im Tunnel sind extrem feindselig und scheinen nicht zu zögern, durch den Tunnel reisende Leute anzugreifen. Ihr seid aber offenbar hart genug im Nehmen, also solltet ihr wahrscheinlich sicher sein.\n\nEine Wegbeschreibung? Wenn Ihr mit Senir sprechen wollt, findet Ihr ihn in Kharanos.\n\nArbeitet Euch durch den Tunnel und folgt einfach weiter der Straße, wenn Ihr auf der anderen Seite herauskommt, denn sie führt direkt nach Kharanos.", sourceObjective = "Überbringt Senir Weißbart in Kharanos Grelins Bericht.", sourceObjectiveStatus = "unverified-source-field" }
quests[421] = { id = 421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wertbeweis", description = "Fürstin Sylvanas hat Varimathras damit beauftragt, die Gebiete der Menschen und Zwerge im Süden zu erobern.\n\nAber dieser Idiot Arugal - ein Scharlatan aus Dalaran und heutzutage eine verfluchte Kreatur der Burg Schattenfang - hat auf verantwortungslose Weise mit seiner Magie den strategischen Stützpunkt des Silberwaldes verheert.\n\nIch brauche einen geschickten Kämpfer, der dabei hilft, die Suppe auszulöffeln, die Arugal uns eingebrockt hat. Beweist Euch mir, indem Ihr 5 Weißskalps des Mondzorns tötet. Man findet die elenden Bestien oft nur ein kleines Stück abseits der Straße, am Fuße des Hügels dort unten.", sourceObjective = "Dalar Morgenweber auf dem Grabmal will, dass Ihr 5 Weißskalps des Mondzorns tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[422] = { id = 422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arugals Torheit", description = "Wie Arugal in die Kirin Tor aufgenommen wurde, ist mir schleierhaft. Seine Zauberkunst schien so billig wie schlecht nachgemachter Schmuck.\n\nAm wichtigsten ist es erst einmal, herauszufinden, welche Art von Magie Arugal genau verwendet hat, damit ich sie gegen ihn verwenden und den Silberwald für die Dunkle Fürstin einnehmen kann.\n\nArugal hielt sich zuerst auf der Weizenfarm etwas nördlich der Brücke auf. Einer der Todespirscher berichtete, dass er einige Zauberbücher gesehen hätte, sie aber nicht beschaffen konnte. Beschafft mir den Zauber namens 'Arznei des Arugal' aus diesen Büchern.", sourceObjective = "Beschafft Dalar Morgenweber auf dem Grabmal die Arznei des Arugal.", sourceObjectiveStatus = "unverified-source-field" }
quests[423] = { id = 423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arugals Torheit", description = "Bei der Untersuchung von Arugals Arbeit haben sich meine schlimmsten Befürchtungen bestätigt. Der alte Taugenichts war nicht einmal qualifiziert genug, um die Nachttöpfe in Dalaran zu leeren, davon, die Kirin Tor in ihrer schwersten Stunde zu repräsentieren, ganz zu schweigen. Narren!\n\nArugal benutzte verzauberte Gegenstände, um seine schwache Magie zu verstärken. Ich muss diese Gegenstände selbst untersuchen. Zieht los und erschlagt so lange Nimmersatts des Mondzorns und Dunkelseelen des Mondzorns, bis Ihr genug ihrer verzauberten Fesseln für meine Nachforschungen gesammelt habt. Man hat diese üblen Kreaturen im Norden und Osten gesehen.", sourceObjective = "Bringt Dalar Morgenweber am Grabmal 6 Nimmersattfesseln und 3 Dunkelseelenfesseln.", sourceObjectiveStatus = "unverified-source-field" }
quests[424] = { id = 424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arugals Torheit", description = "Ich werde tatsächlich länger brauchen, als ich gedacht hätte, die dunklen Geheimnisse hinter den Verzauberungen, die Arugal verwendete, zu entdecken.\n\nIn der Zwischenzeit müsst Ihr Euch um ein kleines Problem kümmern, das unsere Dunkelpirscher entdeckt haben. Es sieht so aus, als hätte Arugal seiner Magie erlaubt, sich bis zur Tiefenfelsmine in den Hügeln im Südosten auszubreiten.\n\nDiese Mine wäre eine ziemlich nützliche Ressource für Varimathras' Vormarsch.\n\nIch will, dass Ihr Grimson den Blassen, den besudelten Großknecht der Mine, enthauptet. Mit seinem Tod sollte die Mine uns gehören.", sourceObjective = "Tötet Grimson den Blassen und bringt seinen Kopf zu Dalar Morgenweber beim Grabmal.", sourceObjectiveStatus = "unverified-source-field" }
quests[425] = { id = 425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ivar der Verfaulte", description = "Mein Bruder Quinn und ich wurden beauftragt, den Silberwald auszukundschaften und Hochexekutor Hadrec Bericht zu erstatten. Aber wir kamen nicht weit - als wir über diese Farm gingen, wurden wir von einem Ghul namens Ivar der Verfaulte angegriffen.\n\nWir entkamen Ivar, aber er verletzte Quinn schwer. Dank des Trankes, den Ihr ihm gegeben habt, heilt er, aber Ivar könnte wiederkommen, bevor Quinn sich erholt hat.\n\nTötet Ivar, damit Quinn genug Zeit hat, sich zu regenerieren. Ivar hält sich üblicherweise in dem Schuppen da drüben auf und wartet darauf, dass meine Wachsamkeit nachlässt.", sourceObjective = "Tötet Ivar den Verfaulten und bringt Ivars Kopf zu Rane Yorick auf dem Ivarfeld.", sourceObjectiveStatus = "unverified-source-field" }
quests[426] = { id = 426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die überrannte Mühle", description = "Die Geißel versucht, bei Agamands Mühlen einen Stützpunkt zu errichten. Wenn ihnen das gelingt, können sie weitere Angriffe innerhalb von Tirisfal unternehmen.\n\nEs wurden klare Befehle erteilt. Die Diener der Geißel in den Mühlen müssen vernichtet werden.\n\nGeht zu den Mühlen. Sammelt schartige Rippen von klappernden Skelettsoldaten und Trümmerschädelsoldaten sowie geschwärzte Schädel von dunklen Skelettmagiern.\n\nUm zu den Mühlen zu gelangen, folgt der Straße westwärts. Nachdem Ihr die Brücke überquert habt, nehmt die erste Abzweigung nach Norden und folgt diesem Weg. Wenn Ihr die Windmühlen seht, beginnt die Schlacht.", sourceObjective = "Sammelt 5 schartige Rippen sowie 3 geschwärzte Schädel und kehrt dann zu Todeswache Dillinger nach Brill zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[427] = { id = 427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Krieg mit dem Scharlachroten Kreuzzug", description = "Die Dokumente, die Exekutor Arren uns zur Verfügung stellte, verschaffen uns genau die Atempause, die wir in unserem Kampf gegen den Scharlachroten Kreuzzug benötigen. Wir kennen jetzt dessen genaue Aufenthaltsorte überall in Tirisfal.\n\nAber leider haben die Todeswachen noch ganz andere Sorgen. Die Armee des Lichkönigs wächst jede Nacht an. Wir benötigen jemanden, der wie Ihr gern \"Initiative\" zeigt, um den Scharlachroten Kreuzzug ins Grab zu bringen.\n\nBeweist mir, dass Ihr der Dunklen Fürstin dienen könnt, indem Ihr nach Westen zum Turm hinter Sollidens Bauernhof reist und dort 10 Scharlachrote Krieger erschlagt.", sourceObjective = "Exekutor Zygand von Brill verlangt, dass Ihr 10 Scharlachrote Krieger tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[428] = { id = 428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorenen Todespirscher", description = "Vor einigen Wochen wurden zwei unserer Todespirscher, Rane und Quinn Yorick, auf eine Aufklärungsmission durch den nördlichen Silberwald geschickt. Wir haben nichts mehr von ihnen gehört.\n\nSie könnten der Geißel zum Opfer gefallen sein, doch wenn dem so ist, will ich es bestätigt wissen. Findet diese Todespirscher.\n\nIhre erste Aufgabe war es, die Bauernhöfe im nördlichen Silberwald auszukundschaften. Ihr solltet dort mit Eurer Suche beginnen.", sourceObjective = "Findet die Todespirscher Quinn und Rane Yorick.", sourceObjectiveStatus = "unverified-source-field" }
quests[429] = { id = 429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilde Herzen", description = "Mein Bruder Quinn wurde von dem Ghul Ivar dem Verfaulten schwer verletzt, und ich glaube nicht, dass er ohne magische Hilfe wieder vollständig genesen wird. Auch wenn ich kein Apotheker bin, so weiß ich doch, dass unsere Apotheker Heiltränke aus verfärbten Worgherzen herstellen können.\n\nSammelt einige solcher Herzen und bringt sie zu Apotheker Renferrel am Grabmal im Süden. Kommt dann mit dem Trank hierher zurück.\n\nZwischen hier und Maldens Obsthain im Osten werdet Ihr jede Menge Worgs vorfinden.", sourceObjective = "Sammelt 6 verfärbte Worgherzen und bringt sie zu Apotheker Renferrel auf dem Grabmal.", sourceObjectiveStatus = "unverified-source-field" }
quests[430] = { id = 430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Quinn", description = "Hier habt Ihr den Trank, mit dem Ihr Quinn Yoricks Erholung beschleunigen könnt.\n\nWenn Ihr mich jetzt entschuldigen mögt, ich habe wirklich wichtige Dinge zu erledigen...", sourceObjective = "Bringt Quinn Yorick auf dem Ivarfeld, nördlich des Grabmals, Quinns Trank.", sourceObjectiveStatus = "unverified-source-field" }
quests[431] = { id = 431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kerze des Heranlockens" }
quests[432] = { id = 432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diese verfluchten Troggs!", description = "Diese vom Licht verfluchten Troggs verwandeln meinen Arbeitsplatz in eine Ruine. Schaut Euch das an, da geht schon wieder ein Pulverfass hoch.\n\nOh, ich wünschte ich könnte da runtergehen und allen einzeln ihre dürren Hälse umdrehen! Ich will sie alle töten!\n\nDas kann nicht gut für meine Gesundheit sein, all dieser Stress und diese Wut... Was haben sie mir gelassen? Nichts!\n\nIch würde sie persönlich umbringen, aber ich ziele nicht mehr so gut wie früher. Geht in den Steinbruch und tötet einige dieser dreckigen Mistviecher! Ich werde Euch bezahlen! Hauptsache, Ihr verletzt sie, tötet sie!", sourceObjective = "Tötet im Steinbruch von Gol'Bolar und in der Mine 8 Schädelhauer der Felsenkiefertroggs und 8 Knochenknacker der Felsenkiefertroggs.", completion = "Nun, jetzt geht es mir schon etwas besser... \n\nAber ich werde mich erst wieder richtig freuen können, wenn sie alle tot sind! Restlos alle!", sourceObjectiveStatus = "unverified-source-field" }
quests[433] = { id = 433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Dienste des Volkes", description = "Als Mitglied des Senats und der Forscherliga habe ich mir vorgenommen, die Zustände im Steinbruch zu inspizieren. Die Troggs sind außer Rand und Band!\n\nSie haben den Gol'Bolar Steinbruch auf den Kopf gestellt. Als wir in die Tiefen des Erdreichs vorstießen, strömten sie ans Tageslicht, zerstörten unsere Ausrüstung und schlossen viele Bergarbeiter untertage ein.\n\nWir müssen sie von hier vertreiben. Ich habe Magier Überstunden machen lassen, damit diese Runen der Rückkehr verzaubert werden. Wenn Ihr sie in die Hände der gefangenen Minenarbeiter bekommen könnt, können sie unbeschadet zur Oberfläche zurückkehren.", sourceObjective = "Verteilt Runen der Rückkehr an 7 gefangene Minenarbeiter in der Gol'Bolarmine.", progress = "Wir müssen die Minenarbeiter in Sicherheit bringen, bevor die Troggs es leid werden, nur mit ihnen zu spielen.", completion = "Was für eine Erleichterung! Ich bin froh, dass es Euch gelungen ist, so viele Minenarbeiter zu retten, {name}. Ich werde sofort ihre Familien in Kenntnis setzen.\n\nDer Senat wird von Eurer Rolle bei der Rückeroberung der Mine erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[434] = { id = 434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Angriff!", description = "Nachdem ich dem Spionagebot die Verkleidung angelegt habe, begibt er sich hinein, um mit Lescovar zu sprechen. Die Wachen sollten ihn ohne Probleme durchlassen.\n\nWährend Ihr Material für mich gesammelt habt, habe ich Marzon darüber informiert, dass es für ihn und Lescovar an der Zeit sei, sich wieder zu treffen. Ich habe sogar einige falsche Informationen verlautbaren lassen.\n\nLescovar wird seine Wachen wegschicken und hier draußen im Garten auf Marzon warten. Tretet in Aktion, wenn Ihr etwas über die Defias hört. Ihr müsst sie beide eliminieren. Kapiert?\n\nWenn Ihr das erledigt habt, sprecht Ihr mit Trias.", sourceObjective = "Bleibt im Garten, bis Lord Gregor Lescovar und Marzon die Stille Klinge ihr Gespräch beendet haben. Schaltet sie danach beide aus, bevor Ihr nach Sturmwind zu Elling Trias zurückkehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[435] = { id = 435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eskorte für Erland", description = "Die Wölfe da draußen wollen nicht abhauen, und jedes Mal, wenn ich einen Schritt aus der Tür mache, schauen sie mich böse an. Sie müssen unglaublich hungrig sein, wenn sie mich für essenswert halten.\n\nIch muss mich bei meiner Kampfgefährtin, Todespirscherin Rane Yorick, melden. Und um zu Rane zu kommen, brauche ich Hilfe gegen diese Wölfe.\n\nBitte begleitet mich! Ach ja, da draußen sind eine Menge Wölfe, wir hätten also eine bessere Chance, wenn Ihr Freunde dabei hättet, die ebenfalls helfen können...", sourceObjective = "Begleitet Erland durch die Wölfe hindurch zu Rane Yorick.", sourceObjectiveStatus = "unverified-source-field" }
quests[436] = { id = 436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisenbands Ausgrabungsstätte", description = "Ausgrabungsleiter Eisenband leitet die Ausgrabung einiger alter Ruinen östlich des Sees. Er hat zuletzt wenig Fortschritte gemacht, besonders, wenn man all den Nachschub bedenkt, den wir ihm geschickt haben.\n\nEisenband ist ein bodenständiger, ehrlicher Zwerg, der gern Resultate sieht, und daher mache ich mir Sorgen, dass da irgendwelche Kräfte gegen ihn arbeiten.\n\nGeht zu Eisenbands Ausgrabungsstätte und sprecht mit Magmar Todesstreich. Er kümmert sich um die Einzelheiten an der Stätte und wird wissen, warum es so langsam voran geht.\n\nUm zur Ausgrabungsstätte zu gelangen, müsst Ihr um die Südspitze des Sees herum und dann nach Osten gehen.", sourceObjective = "Sprecht mit Forscher Todesstreich.", sourceObjectiveStatus = "unverified-source-field" }
quests[437] = { id = 437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Todesfeld", description = "Unsere ursprünglichen Spähberichte über den Silberwald zeigen, dass die Moderfelle auf einer alten Farm im Norden, nahe dem Todesfeld, einen Stützpunkt haben. Wir haben kleine Angriffe auf sie gestartet, aber jedes Mal werden sie von der Banshee Nachtseele unterstützt, die ihre Magie einsetzt, um unsere Truppen in die Flucht zu schlagen.\n\nWir wollen Nachtseele vernichtet sehen.\n\nGeht ins Todesfeld und greift die Moderfelle an. Falls Ihr Nachtseele nicht seht, tötet so lange Moderfellgnolle, bis sie auftaucht, und besiegt sie dann.\n\nIhre Essenz wird zu Staub zerfallen. Bringt mir diesen Staub als Beweis.", sourceObjective = "Tötet Gnolle der Moderfelle auf dem Todesfeld.\n\nSobald Nachtseele auftaucht, tötet sie ebenfalls.\n\nBringt Nachtseeles Essenz zu Hochexekutor Hadrec beim Grabmal.", sourceObjectiveStatus = "unverified-source-field" }
quests[438] = { id = 438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verfallene Fähre", description = "{name}, wir haben ein neues Nest der Geißel entdeckt: Die verfallene Fähre. Die Fähre liegt östlich des Grabmals und wird von Moderfellgnollen und anderen Untoten schwer bewacht.\n\nEs muss einen Grund dafür geben, warum die Geißel dieses Gebiet besetzt hat. Geht zur verfallenen Fähre und findet heraus, warum die Geißel sich dort aufhält.", sourceObjective = "Geht zur verfallenen Fähre.\n\nSucht nach dem Grund, warum die Geißel dort ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[439] = { id = 439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf den Spuren der Moderfelle", description = "Aus den Leichen ragt eine nicht eingewickelte Hand heraus. Es handelt sich um die Hand einer Frau, von der Seuche pockennarbig, aber relativ frisch. \n\nAn der Hand befindet sich ein Ring. Als Ihr den Ring entfernt und untersucht, entdeckt Ihr eine Gravur:\n\n\"Für Deliah.\"", sourceObjective = "Bringt Deliahs Ring zu Hochexekutor Hadrec beim Grabmal.", sourceObjectiveStatus = "unverified-source-field" }
quests[440] = { id = 440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gravierte Ring", description = "Wenn Ihr den Ehemann oder Geliebten finden wollt, der Deliah ihren Ring gab... dann sprecht mit Magistrat Sevren in Brill. Er sollte alle Dokumente über die jüngsten Todesfälle haben und wird mit etwas Glück herausfinden können, wer Deliah ist.\n\nAber ich würde meine Hoffnungen nicht zu hoch stecken. Wer auch immer ihr den Ring gab, ist wahrscheinlich tot. Oder, wenn er untot ist, kümmert Deliah ihn wahrscheinlich nicht mehr.", sourceObjective = "Bringt Deliahs Ring zu Magistrat Sevren nach Brill.", sourceObjectiveStatus = "unverified-source-field" }
quests[441] = { id = 441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raleigh und Unterstadt", description = "Deliah hatte einen Ehemann, Raleigh, der nun in Unterstadt sein Zuhause hat. Wenn die Deliah, die in Brill wohnte, die ist, der dieser Ring gehörte, dann wird es Raleigh wissen.\n\nRaleigh ist im Handwerksviertel von Unterstadt.", sourceObjective = "Bringt Deliahs Ring zu Raleigh.", sourceObjectiveStatus = "unverified-source-field" }
quests[442] = { id = 442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturm auf die Insel Fenris", description = "Es ist an der Zeit, den Standort der Geißel im Silberwald zu stürmen: die Insel Fenris.\n\nIhr müsst Euch noch einmal auf diese Insel begeben und Thule Rabenklaue vernichten. Ich will seinen Kopf!\n\nDiese Mission ist so gefahrvoll, wie sie entscheidend ist, {name}. Ihr dürft nicht scheitern.", sourceObjective = "Bringt Hochexekutor Hadrec auf dem Grabmal Thules Kopf.", sourceObjectiveStatus = "unverified-source-field" }
quests[443] = { id = 443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moderfellsekret", description = "Bevor wir einen Angriff auf die Insel Fenris starten können, müssen wir erst herausfinden, wer hinter den Moderfellgnollen steht. Unsere Apotheker glauben, ihr Ursprung liegt in der seltsamen Flüssigkeit, die durch ihre Körper fließt.\n\nGeht zur Insel Fenris, östlich der verfallenen Fähre, und sammelt Moderfellsekret von den Gnollen dort. Bringt es zu Apotheker Renferrel, draußen vor dem Grabmal.", sourceObjective = "Bringt 8 Flaschen Moderfellsekret zu Apotheker Renferrel beim Grabmal.", sourceObjectiveStatus = "unverified-source-field" }
quests[444] = { id = 444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ursprünge der Moderfelle", description = "Ich habe das Sekret, das Ihr mir gebracht habt, in seine Grundbestandteile aufgelöst. Meine Ergebnisse sind nicht sehr aufschlussreich, aber ich konnte ermitteln, dass Hexenmeister- und Totenbeschwörermagie zur Herstellung des Sekrets verwendet wurden.\n\nWährend ich weiter das Sekret untersuche, möchte ich, dass Ihr eine Probe davon zu Bethor Eismacht nach Unterstadt bringt. Bethor ist kein Apotheker, aber sein Wissen von der Magie könnte uns helfen, das Geheimnis um die Moderfelle zu lüften.\n\nGeht. Ihr dürftet Bethor im Magieviertel von Unterstadt finden.", sourceObjective = "Bringt die Sekretprobe zu Bethor Eismacht nach Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[445] = { id = 445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delivery to Silverpine Forest" }
quests[446] = { id = 446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thule Rabenklaue", description = "Dieses Sekret wurde von einem alten Kollegen von mir hergestellt: Thule Rabenklaue. Vor dem großen Krieg war er ein junger, aufstrebender Magier, aber als der Lichkönig immer mächtiger wurde, verriet er seine Brüder und verbündete sich mit der Geißel.\n\nIch hätte nicht gedacht, dass er noch lebt, geschweige denn, dass er die Moderfelle bei ihren Vorstößen gegen uns anführt.\n\nIch kenne viele seiner Zauber und kann dabei helfen, einen Trank zu brauen, der ihnen entgegenwirkt. Nehmt diese Spruchrolle mit zurück zu Apotheker Renferrel. Auf ihr stehen die Beschwörungsformeln, die man für den Trank braucht.", sourceObjective = "Bringt Bethors Spruchrolle zu Apotheker Renferrel beim Grabmal im Silberwald.", sourceObjectiveStatus = "unverified-source-field" }
quests[447] = { id = 447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rezept für den Tod", description = "Arthas hat Truppen von schier endloser Zahl. Doch mit einer neuen Seuche könnten wir sowohl die Armee der Geißel als auch das menschliche Ungeziefer ein für alle Mal auslöschen.\n\nMeine Studien haben bewiesen, dass Spinnenblut, vermischt mit einem aus dem Herzen eines ergrauten Bären gewonnenen Toxin, zu einem tödlichen Elixier wird. Sammelt Proben von den Spinnen im Huschdunkel im Nordwesten und von den Bären, die im Silberwald umherstreifen. Bringt diese Reagenzien zu Apothekermeister Faranell von der königlichen Apothekervereinigung in Unterstadt.", sourceObjective = "Sammelt 6 Herzen von ergrauten Bären und 6 Proben Huschendes Blut und bringt diese zu Apothekermeister Faranell nach Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[448] = { id = 448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung bei Hadrec", description = "Bevor Ihr einen Angriff auf die Insel Fenris unternehmt, meldet Euch bei Hochexekutor Hadrec. Er könnte zusätzliche Informationen oder Ausrüstung haben, die Ihr brauchen werdet.", sourceObjective = "Meldet Euch bei Hochexekutor Hadrec auf dem Grabmal.", sourceObjectiveStatus = "unverified-source-field" }
quests[449] = { id = 449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bericht der Todespirscher", description = "Auch wenn Quinns Wunden heilen, möchte ich doch unseren Bericht so schnell wie möglich zu Hochexekutor Hadrec bringen. Er enthält Informationen, die für die Besetzung des Silberwaldes durch die Verlassenen von höchster Wichtigkeit sind.", sourceObjective = "Bringt den Todespirscherbericht zu Hochexekutor Hadrec beim Grabmal.", sourceObjectiveStatus = "unverified-source-field" }
quests[450] = { id = 450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rezept für den Tod", description = "Ihr könnt der königlichen Apothekervereinigung noch weiter zu Diensten sein, {name}.\n\nAls Arugal seine elenden Zauber über den Wald gelegt hat, verfluchte er eines unserer vielversprechendsten Mitglieder, Apotheker Berard. Als hirnloser Diener von Arugal ist Berard jetzt für uns nutzlos. Aber seine Erkenntnisse könnten sich als wertvoll erweisen. Er untersuchte eine längst vergessene Seuche, die vor Ewigkeiten einmal alles Leben im Lordameresee getötet hat.\n\nBergt Berards Tagebuch aus seinem Studierzimmer im Gasthaus von Lohenscheit und bringt es zu Apotheker Renferrel.", sourceObjective = "Bergt Apotheker Berards Tagebuch aus Lohenscheit und bringt es zu Apotheker Renferrel beim Grabmal.", sourceObjectiveStatus = "unverified-source-field" }
quests[451] = { id = 451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rezept für den Tod", description = "Laut Berards Tagebuch könnte sich das Moos von Seeschleichern und Seekrabblern bei unserer Suche nach einer neuen Seuche als nützlich erweisen. Diese Bestien leben auf den Inseln im Lordameresee im Osten.\n\nEr erwähnt außerdem einen sehr seltenen verhärteten Tumor, den er bei einem Finsterflossenmurloc entdeckte. Anscheinend war der Tumor so selten, dass Berard nur einen einzigen auftreiben konnte.\n\nSammelt Proben von diesem Moos sowie von dem seltenen verhärteten Tumor und bringt beides zu Apothekermeister Faranell nach Unterstadt.", sourceObjective = "Bringt 6 Proben Seeschleichermoos, 6 Proben Seekrabblermoos und einen verhärteten Tumor zu Apothekermeister Faranell nach Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[452] = { id = 452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinterhalt in Lohenscheit", description = "Ihr kommt gerade rechtzeitig, {name}!\n\nDer Rat von Lohenscheit wird jeden Moment zurückkehren. Arugal muss sich in der Burg um andere Dinge kümmern. Er benutzt den Rat als reine Schachfiguren, um die hirnlosen Diener von Lohenscheit unter seiner Kontrolle zu halten. Aber ich glaube, dass die Söhne von Arugal sich ohne die Führung durch den Rat von Lohenscheit gegen ihren Meister stellen werden.\n\nIch werde nicht allein mit ihnen allen fertig. Ihr müsst mir helfen. Gemeinsam können wir den Rat für Fürstin Sylvanas zerschlagen.", sourceObjective = "Helft Todespirscher Faerleia, den Rat von Lohenscheit zu töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[453] = { id = 453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach der Schattengestalt", description = "Viel Glück, {name}. Ich hoffe, Ihr könnt den Kerl finden, und dass er dann noch am Leben ist.\n\nWenn er die Sicherheit von Dunkelhain hinter sich gelassen hat, könnte er leicht Wildtieren zum Opfer gefallen sein.", sourceObjective = "Findet die Schattengestalt. Eure Hinweise:\n\nEr stammt nicht aus Dunkelhain.\n\nEr ist eine nervöse, hektische Person.\n\nEr verließ Dunkelhain und ging nach Westen.", sourceObjectiveStatus = "unverified-source-field" }
quests[454] = { id = 454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach dem Hinterhalt", description = "Wir hatten vor dieser... Geschichte die Pulverfässer in mehreren Fuhren transportiert. Jetzt müssen wir die Arbeit aufteilen. Miran nimmt die Fässer, und ich passe auf die anderen auf.\n\nIch fühle mich nicht wohl dabei, Miran den Rest der Fracht ganz allein transportieren zu lassen. Vielleicht könntet Ihr ihn auf seiner nächsten Tour begleiten, wenn er fertig zur Abreise ist?", sourceObjective = "Sprecht mit Miran.", sourceObjectiveStatus = "unverified-source-field" }
quests[455] = { id = 455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Algaz-Spießrutenlauf", description = "Orcs vom Drachenmalklan haben im Sumpfland eine Zufluchtstätte. Und jetzt haben sie sich nach Dun Algaz ausgebreitet. Wir können nicht zulassen, dass sie ihren Einfluss auf dieses Gebiet behalten, sonst wird der Loch Modan vom Hafen von Menethil, unserer Hafenfestung im Sumpfland, abgeschnitten.\n\nBrecht durch Dun Algaz in das dahinterliegende Sumpfland durch und tötet dabei ein paar Orcs. Meldet Euch bei Valstag Eisenkiefer im Hafen von Menethil.\n\nNach Menethil kommt Ihr, indem Ihr Dun Algaz durchquert, anschließend nordwärts der Straße folgt und Euch dann an der Biegung westwärts haltet.\n\nWir verlassen uns auf Euch, {name}. Ihr dürft nicht scheitern.", sourceObjective = "Durchquert Dun Algaz.\n\nTötet 8 Späher des Drachenmals und 6 Grunzer des Drachenmals.\n\nMeldet Euch bei Valstag Eisenkiefer im Hafen von Menethil.", sourceObjectiveStatus = "unverified-source-field" }
quests[456] = { id = 456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gleichgewicht der Natur", description = "Seid gegrüßt, {name}. Ich bin Konservator Ilthalaine. Meine Aufgabe im Laubschattental ist es, für den Erhalt des Gleichgewichts der Natur zu sorgen.\n\nDie Frühjahrsniederschläge waren dieses Jahr besonders heftig, was dafür sorgte, dass einige Tiere des Waldes gediehen, während andere darunter litten.\n\nUnglücklicherweise sind die Bestände an Nachtsäblern und Distelebern zu stark angewachsen. Das Laubschattental kann nur eine gewisse Menge Futter für diese Tiere erzeugen. Zieht los, {class}, und dünnt die Eber- und Säblerpopulation etwas aus, auf dass die Harmonie der Natur erhalten bleibt.", sourceObjective = "Tötet 3 junge Nachtsäbler sowie 3 junge Disteleber.", sourceObjectiveStatus = "unverified-source-field" }
quests[457] = { id = 457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gesetz der Natur", description = "Die Jungbestände einiger Kreaturen hier im Laubschattental auszudünnen, war ein guter Anfang, {name}, aber es gibt immer noch etwas zu tun.\n\nDie Ressourcen des Waldes werden sich zu schnell erschöpfen, wenn sich niemand um das Problem kümmert. Mutter Naturs Wildtiere zu töten, ist ein notwendiges Übel zum Besten von allen, die sich das Land teilen. Begebt Euch in den Nordosten des Waldes und erschlagt im Namen des Gleichgewichts räudige Nachtsäbler und Disteleber.", sourceObjective = "Tötet 6 räudige Nachtsäbler und 6 Disteleber.", sourceObjectiveStatus = "unverified-source-field" }
quests[458] = { id = 458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Beschützerin des Waldlandes", description = "Was ein Glück, dass Ihr hier seid, {class}. Vom Wispern der Waldgeister wurden mir seltsame Neuigkeiten zugetragen.\n\nDie geheimnisvolle Beschützerin des Waldlandes, Tarindrella, ist in das Laubschattental zurückgekehrt. Jahrelang war die Gegenwart der Dryade in den Wäldern Kalimdors nicht zu spüren. Sicherlich stimmt irgendetwas nicht, wenn sie jetzt wieder in diese Gegend zurückgekommen ist.\n\nSucht Tarindrella und findet heraus, was sie in unseren Hain führt. Eine der Schildwachen berichtete, sie südwestlich von Aldrassil gesehen zu haben.", sourceObjective = "Sucht die Dryade, die als Tarindrella bekannt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[459] = { id = 459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonische Diebe", description = "Teuflische kleine Grells! Die haben sich wieder an unseren Nahrungsvorräten bedient. \n\nWenn Ihr nichts dagegen hättet, uns zur Hand zu gehen: Was auch immer sie gestohlen haben, liegt sicherlich in den Lagern der Grells westlich von hier verstreut. Ich würde Euch mit Freuden belohnen, wenn ihr alles zu mir zurückbringen könntet.", sourceObjective = "Bringt Dellylahs gestohlene Bohnen, Dellylahs gestohlenes Wasser und Dellylas gestohlene Beutel zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[460] = { id = 460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resting in Pieces" }
quests[461] = { id = 461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die versteckte Nische", description = "Ich kenne eine versteckte Nische in der Burg, die einen Gegenstand enthält, der für Thule und seine alten Kollegen sehr wichtig ist. Außerdem enthält sie noch etwas, das Ihr nützlich finden könntet. Bringt mich dorthin!\n\nDie Nische ist im Südwestturm der Burg, hinter einem staubigen Regal.\n\nNehmt meinen Körper mit, aber lasst die Stiefel hier. Die haben mir sowieso nie richtig gepasst.", sourceObjective = "Bringt Alaric zur versteckten Nische.", sourceObjectiveStatus = "unverified-source-field" }
quests[463] = { id = 463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sumpfhüter", description = "Ihr habt vom Sumpfhüter gehört? Ihr sucht doch nicht etwa nach ihm, oder? Nun, ich behaupte ja, Ihr seid verrückt, wenn dem so ist, aber wer bin ich, dass ich <einen Narren/eine Närrin> davon abhalte, in den Tod zu gehen?\n\nFalls Ihr ihn sucht - hmmm, ich habe gehört, er sei in den Marschen, ostwärts von dort, wo die Straße nach Dun Modr abzweigt. Er lungert dort bei den Krokis und Schlimmerem herum!\n\nAch, und lasst Euer Geld besser hier. Ihr werdet es dort, wo Ihr hingeht, nicht brauchen... und Ihr wollt doch sicher nicht, dass der alte Grünling sich an Eurem Gold einen Zahn ausbricht, wenn er Euch mittendurch beißt.", sourceObjective = "Findet den Sumpfhüter.", sourceObjectiveStatus = "unverified-source-field" }
quests[464] = { id = 464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsflaggen", description = "Der orcische Drachenmalklan war am Ende des zweiten Krieges so gut wie vernichtet, nachdem er die Kontrolle über ihre Schoßtierchen, die roten Drachen, verloren hatte. Die Drachen waren nicht sehr freundlich zu ihren früheren Herren und machten gnadenlos Jagd auf die Drachenmalorcs. Die wenigen, die überlebten, flohen aus Grim Batol in die Berge östlich von Whelgars Ausgrabungsstätte.\n\nJetzt haben sie an Stärke gewonnen und besitzen ein Lager nordöstlich von Menethil.\n\nWir wollen, dass Ihr dieses Lager angreift. Sammelt und bringt mir ihre Kriegsflaggen als Beweis.", sourceObjective = "Bringt Hauptmann Starkfaust 8 Kriegsflaggen des Drachenmals.", sourceObjectiveStatus = "unverified-source-field" }
quests[465] = { id = 465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nek'roshs Schachzug", description = "Während Ihr die Orcs des Drachenmalklans bekämpft habt, haben wir mehr über deren Pläne herausgefunden.\n\nNek'rosh hat Katapulte gebaut und beabsichtigt, Menethil zu belagern! Und dank der Kämpfe in Dun Algaz sind wir effektiv von Verstärkungstruppen abgeschnitten!\n\nIhr müsst diese Katapulte zerstören. Sie befinden sich im Lager des Drachenmalklans.\n\nHier, nehmt diesen Zunder. Kämpft Euch zu den Katapulten durch und lasst sie mit dem Zunder in Flammen aufgehen.\n\nUnd nachdem Ihr das getan habt, findet und tötet Nek'rosh. Wir müssen dieser Drachenmalbestie den Kopf abschlagen.", sourceObjective = "Zerstört die Katapulte des Drachenmals.", sourceObjectiveStatus = "unverified-source-field" }
quests[466] = { id = 466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Pyrophor", description = "Ich habe gehört, im Sumpfland wurde in einer Höhle nordwestlich vom Algaz-Tor ein seltenes Erz namens Pyrophor gefunden. Pyrophor ist instabil und schwer anzuwenden, ohne sich dabei selbst in die Luft zu sprengen, aber ich bin mir sicher, wenn man es auf die richtige Art und Weise verhüttet, könnte man daraus Kanonenkugeln mit einer ziemlichen Durchschlagskraft herstellen.\n\nBesorgt mir Pyrophorerz und ich finde jemanden, der mutig genug ist, damit zu experimentieren.\n\nOh, und um dieses Erz aus einer Ader zu schürfen, müsst Ihr Euch mit Bergbau auskennen. Wenn dem nicht so ist, dann... nehmt einen Freund mit in diese Höhle, der es tut!", sourceObjective = "Bringt 6 Ladungen Pyrophorerz zu Pilot Steinsegel nach Dun Morogh.", sourceObjectiveStatus = "unverified-source-field" }
quests[467] = { id = 467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steinsegels Suche", description = "Pilot Steinsegel liebt seine Belagerungsmaschine, wie jeder Pilot es auch sollte! Und er ist immer begierig, neue Wege zu finden, die Feuerkraft seines Panzers zu vergrößern!\n\nEr hat Gerüchte über ein seltenes Erz gehört und sucht jetzt nach jemandem, der es für ihn auftreibt. Wenn es Euch also in den Fingern juckt, dann sucht Steinsegel in Stahlrosts Depot in Dun Morogh auf und schaut mal, was er will.", sourceObjective = "Sprecht mit Pilot Steinsegel.", sourceObjectiveStatus = "unverified-source-field" }
quests[468] = { id = 468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung bei Gebirgsjäger Felsgar", description = "Gebirgsjäger Felsgar sucht nach Freiwilligen für eine Mission durch Dun Algaz und in das Sumpfland hinein. \n\nWenn Ihr also Lust habt, Euch Eure Stiefel in dieser sumpfigen Gegend im Norden schmutzig zu machen, dann sprecht mit Felsgar in Dun Algaz. Dun Algaz liegt weiter die Straße entlang im Norden, hinter dem Wachturm.", sourceObjective = "Sprecht mit Gebirgsjäger Felsgar.", sourceObjectiveStatus = "unverified-source-field" }
quests[469] = { id = 469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tägliche Lieferung", description = "Seid gegrüßt!\n\nIhr seid nicht zufällig in Richtung Menethil unterwegs? Falls nicht, würde ich Euch empfehlen, dort Halt zu machen, denn es ist ein guter Ort, um Waren zu kaufen oder etwas trinken zu gehen und sich auszuruhen.\n\nTja, wenn Ihr also zufälligerweise in diese Richtung unterwegs seid, dann habt Ihr doch sicher nichts dagegen, dieses Bündel Krokiliskenhäute zu James Halloran, dem Gerber, zu bringen?\n\nIch würde es ja selbst tun, aber meine Frau ist in letzter Zeit ziemlich launisch, und ich würde es gern so lange wie möglich aufschieben, ihr zu begegnen.", sourceObjective = "Liefert das Bündel Krokiliskenhäute bei dem Gerber James Halloran im Hafen von Menethil ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[470] = { id = 470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stochern im Schlamm", description = "Bei meinem wöchentlichen Besuch an Eisenbarts Grabmal wurde ich von grässlichen, triefenden Schlammen angegriffen! Natürlich geriet ich in Panik.\n\nIch habe meine Tasche nach einem geworfen, aber das zeigte keinerlei Wirkung! Der Schlamm saugte sie einfach auf... Glücklicherweise gab mir das genug Zeit wegzulaufen.\n\nDie schlechte Nachricht ist, dass ich dringend den Inhalt meiner Tasche benötige!\n\nIch weiß nicht, nach welchem Schlamm ich meine Tasche geworfen habe; sie sehen alle gleich aus! Eisenbarts Grabmal liegt nordöstlich von hier, in der Nähe von Dun Modr. Ich danke Euch wirklich sehr!", sourceObjective = "Ein Schlamm bei Eisenbarts Grabmal hat Sidas Tasche. Bergt sie und bringt sie ihr zurück in den Hafen von Menethil.", sourceObjectiveStatus = "unverified-source-field" }
quests[471] = { id = 471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lehrlingspflichten", description = "Ich habe meinen Lehrling in die Marschen geschickt, um einige unserer berühmten riesigen Sumpflandkrokilisken zu häuten. Als er nicht zurückkam, bin ich losgezogen, um ihn zu suchen... Sagen wir einfach, es war kein schöner Anblick.\n\nDie Schwester sagt, er könnte durchkommen, aber derweil brauche ich immer noch meine Häute!\n\nUnd wenn Ihr noch ein paar von den Monstern töten wollt, hätte ich nichts dagegen, nach allem, was sie getan haben. Ihr findet die Krokis, wenn Ihr die Küste entlang nach Norden geht, hinter den Hütten der Murlocs.", sourceObjective = "Sammelt 6 riesige Krokiliskenhäute und bringt sie zu James Halloran in den Hafen von Menethil.", sourceObjectiveStatus = "unverified-source-field" }
quests[472] = { id = 472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fall von Dun Modr", description = "Dun Modr ist an die Dunkeleisenzwerge gefallen!\n\nMeine Wunden sind schwer, {class}. Ein Großteil meines Regiments wurde getötet! Diese Rohlinge der Dunkeleisenzwerge haben uns angegriffen, bevor wir uns nach dem Überfall auf den Thandolübergang wieder sammeln konnten.\n\nUnser Anführer, Langzopf, blies zum Rückzug. Als wir die Stadt verließen, wurde ich von einer verirrten Axt in den Rücken getroffen und alles wurde schwarz um mich.\n\nIch wachte hier in Menethil auf, aber ich fürchte um meine Kameraden. Ich hege allerdings noch Hoffnung. Vielleicht ist Langzopf noch am Leben! Seht nach, ob Ihr ihn in der Nähe von Dun Modr finden könnt, {race}!", sourceObjective = "Sucht nahe der Stadt von Dun Modr nach Langzopf.", sourceObjectiveStatus = "unverified-source-field" }
quests[473] = { id = 473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung bei Hauptmann Starkfaust", description = "{name}. Der Drachenmalklan der Orcs zeigt nicht nur in Algaz Stärke. Hauptmann Starkfaust wünscht mit denen zu sprechen, die Hilfe gegen diese Orcs anbieten wollen. Er ist in der Burg, im Kriegsraum.", sourceObjective = "Sprecht mit Hauptmann Starkfaust.", sourceObjectiveStatus = "unverified-source-field" }
quests[474] = { id = 474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sieg über Nek'rosh", description = "Jetzt, nachdem die Katapulte abgebrannt wurden, sucht und tötet Häuptling Nek'rosh.", sourceObjective = "Tötet Häuptling Nek'rosh.\n\nBringt Nek'roshs Kopf zu Hauptmann Starkfaust.", sourceObjectiveStatus = "unverified-source-field" }
quests[475] = { id = 475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein beunruhigender Wind", description = "Ein beunruhigender Wind weht durch den Wald.\n\nGaerolas Talvethren dient den schlafenden Druiden der Kralle in den Grabhügeln von Ban'ethil als Großer Aufseher. Seine Pflicht als auserwählter Beschützer der Schlafenden ist es, deren Sicherheit zu gewährleisten, auf dass sie ihrem Pakt mit Ysera gerecht werden.\n\nAber es gab länger keine Nachricht von Gaerolas, und ich werde etwas nervös. Reist nach Osten, zum Dorf Sternenhauch, und bringt mir einen Bericht von Gaerolas, auf dass ich meine Sorgen begraben kann, da ich weiß, dass meine träumenden Brüder und Schwestern sicher schlummern.", sourceObjective = "Sucht Gaerolas Talvethren im Dorf Sternenhauch auf.", completion = "Dank sei den Waldgeistern, dass Ihr hier seid! Ich wusste, Athridas würde die Probleme spüren und Hilfe schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[476] = { id = 476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verderbnis der Knarzklauen", description = "Der Knarzklauenstamm ist wieder verderbt worden!\n\nSie haben mich hinterrücks überfallen, als ich auf dem Weg zum Grabhügel von Ban'ethil war und liefen weiter, um Sternenhauch zu plündern. Irgendetwas im Wald hat Ursal den Raufer, ihren Häuptling, verderbt und er benutzt die bösen Mächte des Teufelsmooses, um sie wahnsinnig werden zu lassen.\n\nIch bin zu schwer verwundet, um zu Athridas zurückkehren und ihm diese schlimme Nachricht überbringen zu können. <Junger/Junge:c> {class}, diese Aufgabe bleibt Euch überlassen. Wir können nur hoffen, dass die verrückten Knarzklauen noch nicht bis nach Ban'ethil durchgedrungen sind!", sourceObjective = "Kehrt zu Athridas Bärenfell in Dolanaar zurück.", completion = "Bei den Sternen! Dies ist wirklich sehr furchterregend!\n\nWir hatten bereits in der Vergangenheit Schwierigkeiten mit der Verderbnis der Furbolgs, doch diese Probleme sollten seit der Reinigung von Teldrassil der Vergangenheit angehören. Ich fürchte um unser gesamtes Volk, falls der Segen der Aspekte selbst unseren großen Baum nicht zu läutern vermag.", sourceObjectiveStatus = "unverified-source-field" }
quests[477] = { id = 477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grenzübergänge", description = "Wie Ihr vielleicht bereits wisst, die Stadt Mühlenbern ist weiterhin eine Quelle der menschlichen Opposition, die nötige Unterstützung erhalten sie meist durch die Hexer von Dalaran.\n\nIch weiß nicht, wie ihr Plan aussieht, aber ihr Interesse an einem Hinterwäldlerdorf wie Mühlenbern zeigt mir, dass es von größerer Bedeutung sein muss.\n\nVom Hügelland aus haben sie wagenweise Kisten geliefert. Viele dieser Vorräte werden in ein kleines Camp nördlich von Lohenscheit gebracht. Bringt mir den Inhalt einer dieser Kisten.", sourceObjective = "Holt den Inhalt einer der Kisten von den Hexern aus Dalaran. Ihr findet Lohenscheit im Süden.", sourceObjectiveStatus = "unverified-source-field" }
quests[478] = { id = 478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Karten und Runen", description = "<Schnell entnehmt Ihr den Anhänger aus der Kiste und setzt den Deckel wieder auf.>", sourceObjective = "Bringt den seltsamen Anhänger zu Schattenpriester Allister in dem Grabmal.", sourceObjectiveStatus = "unverified-source-field" }
quests[479] = { id = 479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachforschungen in Mühlenbern", description = "Dalar versucht, die Quelle für die Zaubereien der Hexer zu finden. In der Zwischenzeit müssen wir ihren Fortschritt mit allen Mitteln aufhalten...\n\nAlle Herbeizauberer, Magier und Beschützer tragen mit Sicherheit ihre Anhänger. Nehmt sie ihnen ab und bringt sie hierher.\n\nFolgt der Hauptstraße in südlicher Richtung und nehmt dann die östliche Abzweigung nach Mühlenbern.", sourceObjective = "Beschafft 8 Anhänger aus Dalaran für Schattenpriester Allister beim Grabmal.", sourceObjectiveStatus = "unverified-source-field" }
quests[480] = { id = 480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wirker", description = "Ein Erzmagier von großer Macht leitet die Reaktivierung des Leyenergieknotens. Angesichts ihres Fortschritts liegt unsere einzige Hoffnung, sie noch aufzuhalten, darin, ihn zu töten. Das ist eine schwierige Tat, denn ohne Zweifel wird er von anderen Magiern und Wärtern beschützt.\n\nIhr müsst ihn schnellstens erledigen. Bringt mir seinen Stab, sobald er tot ist. Geht jetzt.", sourceObjective = "Tötet den Erzmagier von Dalaran und bringt seinen Stab zu Schattenpriester Allister in dem Grabmal.", sourceObjectiveStatus = "unverified-source-field" }
quests[481] = { id = 481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dalars Analyse", description = "Bringt den Anhänger zu Dalar Morgenweber, vielleicht kann er Licht in das Dunkel der Hexerpläne bringen.", sourceObjective = "Bringt den mit Runen gravierten Anhänger zu Dalar Morgenweber in dem Grabmal.", sourceObjectiveStatus = "unverified-source-field" }
quests[482] = { id = 482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dalaran Absichten", description = "Natürlich! Wie konnte ich das vergessen?\n\nMühlenbern war einer der Orte, die von den Kirin Tor gekennzeichnet wurden, weil dort ein ruhender Leyenergieknoten liegt. Mit Sicherheit haben die Hexer vor, diesen Knoten wiederzuerwecken und seine Energien für etwas Größeres zu nutzen.\n\nDas dürfen wir nicht zulassen...\n\nUm die Leyenergien des Gebietes zu aktivieren, bedarf es einer großen Macht. Wir können sie aufhalten, indem wir die Anhänger der Hexer an uns nehmen.\n\nBringt diese Information zu Allister, er wird dann über das weitere Vorgehen entscheiden.", sourceObjective = "Sprecht mit dem Schattenpriester Allister in dem Grabmal.", sourceObjectiveStatus = "unverified-source-field" }
quests[483] = { id = 483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Relikte des Erwachens", description = "Eindringlinge der Knarzklauen wurden beim Überfall auf die Grabhügel von Ban'ethil im Westen gesehen.\n\nWenn wir ihnen nicht zu Hilfe kommen, werden die schlummernden Druiden auf ewig im Smaragdgrünen Traum gefangen gehalten, vollkommen ahnungslos ihrem Schicksal ausgeliefert. Das empfindliche Ritual des Großen Schlafes kann ohne die Relikte des Erwachens nicht unterbrochen werden.\n\nReist zum Höhlenbau und bringt den Rabenkrallentalisman, den schwarzen Federkiel, den Saphir des Himmels sowie die Rune des Nistens herbei. Die Druiden bewahren sie in heiligen Truhen auf. Bringt sie zu mir, damit ich das Aufweckungsritual vorbereiten kann.", sourceObjective = "Bergt die Relikte des Erwachens.", progress = "{name}, die entführten Druiden der Kralle werden auf ewig im Smaragdgrünen Traum gefangen gehalten, wenn wir die Relikte des Erwachens nicht aus dem Grabhügel von Ban'ethil im Westen herbringen können.\n\nJede Minute, die wir zögern, bringt ihr Schicksal einen Schritt näher an die ewige Verdammnis.", completion = "Ihr hattet Erfolg, junger {class}! Gut gemacht. Und gerade rechtzeitig, wie ich hinzufügen möchte.", sourceObjectiveStatus = "unverified-source-field" }
quests[484] = { id = 484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Häute junger Krokilisken", description = "Ich bin James Halloran, der Gerber. Meine gegerbten Krokiliskenhäute sind nah und fern begehrt, Lieferungen gehen per Schiff zu allen Häfen der Welt.\n\nHabt Ihr Einar getroffen? Er ist einer der Jäger, die mir Krokiliskenhäute bringen.\n\nMir fehlen zurzeit weichere Häute, wie die von jungen Krokilisken.\n\nDa ich bald keine mehr habe, bin ich bereit, Euch einen Spitzenpreis für einen Stapel der Häute zu bezahlen. Ihr könnt die jungen Krokis in den Marschen gleich außerhalb der Stadt finden.", sourceObjective = "Besorgt Euch 4 Häute junger Krokilisken für James Halloran im Hafen von Menethil.", sourceObjectiveStatus = "unverified-source-field" }
quests[485] = { id = 485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht OOX-09/HL!", description = "Ihr habt ein merkwürdiges Gerät aus Metall entdeckt, das die Form eines Eis hat. Als Ihr einen der Knöpfe berührt, erwacht das Ei zu Leben und verwandelt sich in eine Art Gnom-Roboter-Apparat! Aus dem Inneren des Roboteis erklingt eine rasselnde Stimme.\n\n\"Mein Name ist Glotz Widrikus und mein Leitroboter ist abgestürzt! Ich werde Euch belohnen, wenn Ihr ihn aufspürt. Bringt dem Roboter bitte diesen Signalgeber!\n\nIch habe jetzt die Koordinaten des Roboters für Euch berechnet. Er ist in der Nähe vom Lauerfels abgestürzt, dort, wo der Fluss entspringt!\"", sourceObjective = "Bringt das Notsignal zu Glotz' Leitroboter an der Quelle des Flusses im Hinterland, in der Nähe vom Lauerfels.", progress = "Ihr habt anscheinend das Wrack eines... Robothuhns entdeckt... Aus dem Ei erklingt wieder die rasselnde Stimme:\n\n\"Ja, hervorragende Arbeit! Das ist tatsächlich mein Leitroboter, aber meine Sensoren zeigen an, dass er Starthilfe benötigt, bevor er zur Reparatur nach Beutebucht zurückfliegen kann. Bitte legt den Signalgeber in den Rover. Der Signalgeber wird den Rest übernehmen!\"", completion = "Ihr legt das Ei... das Notsignal... in das Huhn... den Leitroboter.\n\nAus dem Roboter ertönt ein Brummen und Surren, als er versucht aufzustehen. Nachdem der Roboter zum Leben erwacht ist, ertönt die Stimme von Glotz ein weiteres Mal, diesmal aus dem Inneren des Roboters:\n\n\"OOX-09/HL funktioniert endlich, aber es sind umfangreiche Reparaturen erforderlich! Er ist zu schwer, als dass Ihr ihn tragen könntet... aber ich glaube, ich habe eine Idee. Könntet Ihr noch etwas auf ihn aufpassen?\"", sourceObjectiveStatus = "unverified-source-field" }
quests[486] = { id = 486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ursal der Raufer", description = "Jetzt ist die Zeit gekommen, die Druiden der Kralle zu retten. {name}, sollten wir jetzt versagen, sind sie für immer im Schlaf verloren.\n\nIch werde die Relikte des Erwachens vorbereiten und das Ritual durchführen. Damit meine Arbeit Wirkung zeigen kann, muss die verfluchte Bestie, die für diese schreckliche Situation verantwortlich ist, getötet werden. \n\nEs war Ursal der Raufer, der sich in die Berufung unserer Brüder eingemischt hat, und er ist es auch, der nun bezahlen muss, damit sie befreit werden können. Reist auf der Straße nach Nordwesten und macht den Pfad nach Norden ausfindig, der Euch in die Kluft führt. Dort werdet Ihr auf Ursals Höhle treffen.", sourceObjective = "Tötet Ursal den Raufer.", completion = "{name}, Ihr habt Euch als ein zutiefst würdiger und geschickter {class} erwiesen. Ein {race}, welcher dem Pfad der Ehre so sicher folgt wie Ihr, findet mit Sicherheit großen Ruhm in dieser Welt.\n\nUrsals Tod bringt unseren einst schlummernden Druiden Sicherheit, doch die Quelle dieser Korruption ist noch immer in unseren Wäldern. Ich vertraue darauf, dass Ihr dieses Böse mit der Zeit finden und läutern könnt, zum Wohle unseres ganzen Volkes. Ihr seid zu Großem bestimmt, junger {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[487] = { id = 487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Straße nach Darnassus", description = "Die Straße nach Darnassus muss sicher bleiben. Reisende, die von Dolanaar nach Darnassus fuhren, haben von ruchlosen Angriffen der verderbten Furbolgs des Knarzklauenstammes berichtet.\n\nJeden Tag gelangen auf diesem Weg wichtige Nachrichten und auch Waren von und nach Darnassus. Es darf einfach nicht sein, dass eine schurkische Bande von Heiden alle terrorisiert.\n\n{class}, greift im Namen des Heiligen Waldes zu den Waffen. Ihr Bau liegt am Ende dieses nördlichen Pfades. Erschlagt die Wegelagerer der Knarzklauen und erstattet mir dann Bericht.", sourceObjective = "Erschlagt 8 Wegelagerer der Knarzklauen.", completion = "Ihr habt den guten Leuten von Dolanaar und Darnassus gute Dienste geleistet, tapferer {class}. Als Mitglied der Schildwache von Teldrassil begrüße ich Euren Einsatz.", sourceObjectiveStatus = "unverified-source-field" }
quests[488] = { id = 488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zenns Aufträge", description = "Ihr seid bereit zu arbeiten, wie ich sehe. Ihr habt Glück, denn es vergeht kein Tag, an dem ich mir nicht wünschte, <ein junger/eine junge:c> {class} wäre hier, <der/die:c> mir zur Hand geht.\n\nWisst Ihr, {name}, ich kann Euch zu Eurem Glück verhelfen und mit Dingen versorgen, von denen Ihr nie zu träumen wagtet. Damit dies jedoch geschieht, müsst Ihr mir gewisse Dinge beschaffen.\n\nMeine Angelegenheiten im Wald erfordern oft gewisse... Reagenzien. Bringt mir Nachtsäblerfangzähne, Strigideulenfedern sowie Proben der Waldweberspinnenseide.\n\nDas soll unser kleines Geheimnis bleiben, {race}.", sourceObjective = "Erhaltet 2 Nachtsäblerfangzähne, 2 Strigideulenfedern und 2 Proben Waldweberspinnenseide.", progress = "Wart Ihr ein fleißiges Bienchen, {name}? Ich warte darauf, dass Ihr mir das bringt, was ich benötige.", completion = "Ha ha! Wirklich hervorragend.\n\nWer hätte jemals gedacht, dass ein {race} mir, Zenn Faulhuf, meine Wünsche erfüllen würde? Selbst ich hätte es nicht geglaubt. Aber so geht es nun mal... unsere so geliebte Welt ist doch voller Überraschungen.\n\nEin Hoch auf die Naiven und Gutgläubigen!", sourceObjectiveStatus = "unverified-source-field" }
quests[489] = { id = 489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht Befreiung!", description = "Der Rat des Waldes hat die Meldung erhalten, dass Ihr Zenn Faulhuf behilflich gewesen seid. Der Satyr ist ein Feind des Waldes. Als {race} müsstet Ihr eigentlich mehr Verstand haben, als den Wald zu entweihen, indem Ihr Kreaturen der Natur tötet.\n\nIhr müsst Eure Ehre in den Augen des Rates wiederherstellen, wenn Ihr weiterhin <ein Freund/eine Freundin> von Teldrassil bleiben wollt.\n\nErteilt Faulhuf eine Lektion, dann habt Ihr Eure Schuld beglichen. Teufelszapfen sind verderbte Samen, die von Bäumen fallen. Sie sondern grünen Rauch ab.\n\nGebt Faulhuf einige davon. Er wird denken, dass Ihr ihm eine harmlose Leckerei gebracht habt.", sourceObjective = "Sammelt 3 Teufelszapfen.", progress = "Was habt Ihr für mich, {name}? Eine leckere kleine Zwischenmahlzeit, nehme ich an?", completion = "Ihr seid ein netter {race}! Ich wusste, dass Ihr nützlich sein würdet!", sourceObjectiveStatus = "unverified-source-field" }
quests[491] = { id = 491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zauberstab an Bethor", description = "Thule erzählte mir einmal, dass er und zwei Kollegen vor langer Zeit einen magischen Zauberstab herstellten, der aus den Lehrlingszauberstäben zusammengewoben wurde, den jeder Magier besaß. Dieser Zauberstab war ein Symbol ihrer Freundschaft, und obwohl Thule ihn hinterher verachtete, konnte er sich doch weder davon trennen noch ihn den anderen überlassen. Also stahl er den Zauberstab und versteckte ihn in Burg Fenris.\n\nHier. Bringt den Zauberstab zu Bethor Eismacht, einem Freund von Thule aus vergangenen Zeiten. Ich bin sicher, er möchte ihn haben.", sourceObjective = "Bringt den gewebten Zauberstab zu Bethor Eismacht in das Magieviertel von Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[492] = { id = 492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine neue Seuche", description = "Berichten der Todeswachen zufolge wurde gerade ein weiterer dieser dummen Zwergengebirgsjäger gefangen genommen. Die Todeswächter benutzen gern den Keller der Taverne Zur Galgenschlinge als Übergangszelle, bis man sich \"richtig\" um die Gefangenen kümmern kann.\n\nWarum... kümmert... Ihr Euch nicht um den gefangenen Gebirgsjäger und schaut, wie er das Spezialgetränk verträgt, das ich für ihn gemacht habe? Das ist nur ein kleiner Eindruck dessen, was die Dunkle Fürstin für den Rest von Azeroth geplant hat.", sourceObjective = "Bringt Johaans Spezialgetränk zum gefangenen Gebirgsjäger.", sourceObjectiveStatus = "unverified-source-field" }
quests[493] = { id = 493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise in das Vorgebirge des Hügellands", description = "Die Königliche Apothekervereinigung steht unter enormem Druck seitens der Dunklen Fürstin, eine neue Seuche zu entwickeln. Wir arbeiten sehr hart und haben bereits einige Fortschritte gemacht. Wir denken, dass der Erfolg sich umso schneller einstellen wird, wenn wir innerhalb der Vereinigung Informationen austauschen.\n\nAus diesem Grunde möchte ich, dass Ihr meine letzten Funde Apotheker Lydon in Tarrens Mühle überbringt, einem kleinen Städtchen, das sich im Vorgebirge des Hügellands befindet. Die Reise wird sehr lange dauern.\n\nBegebt Euch Richtung Süden und bleibt auf den Straßen. Beachtet die Schilder auf das Genaueste!", sourceObjective = "Bringt die Funde von Apotheker Renferrel zu Apotheker Lydon nach Tarrens Mühle im Vorgebirge des Hügellands.", sourceObjectiveStatus = "unverified-source-field" }
quests[494] = { id = 494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit zum Zuschlagen", description = "Schweigt und passt auf, {class}.\n\nIch wurde an diesen Ort geschickt, um die Stadt Hügellandhof zu sondieren. Es handelt sich um eine Aufklärungsmission. Dabei ist von äußerster Wichtigkeit, dass Ihr sofort die Hochexekutorin Darthalia in Tarrens Mühle benachrichtigt. Bestellt ihr, ich, Todespirscherin Lesch, lasse ihr folgende Nachricht ausrichten:\n\n\"Der Schrei des Raben locket vom Westen her.\"\n\nFolgt der Straße gen Osten und beachtet die Schilder genau. Nun aber schnell! Macht Euch auf den Weg nach Tarrens Mühle. Es ist Eile geboten!", sourceObjective = "Reist nach Tarrens Mühle, um die Nachricht von Todespirscherin Lesch an Hochexekutorin Darthalia zu überbringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[495] = { id = 495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone des Willens", description = "Mug'Thol und seine Ogerkriegsmeute wurden nach Alterac geschickt, um die Krone des Willens für Fürstin Sylvanas zu holen. Anstatt sie zurückzubringen, hat der Idiot allerdings versucht, sie aufzusetzen... Oger können wohl einfach keinen Dingen widerstehen, die glitzern und schimmern, nehme ich an.\n\nSeine stümperhaften Aktionen sind allerdings zu einem Problem geworden. Die Krone des Willens hat ihm geholfen, der Besessenheit zu widerstehen, die ihm auferlegt wurde, damit er Fürstin Sylvanas dient.\n\nDie Dunkle Fürstin möchte ein Exempel statuieren. Begebt Euch nach Tarrens Mühle im Hügelland und meldet Euch bei Melisara, meinem dortigen Offizier.", sourceObjective = "Meldet Euch bei Melisara in Tarrens Mühle im Vorgebirge des Hügellands.", sourceObjectiveStatus = "unverified-source-field" }
quests[496] = { id = 496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixier des Leidens", description = "Ah, und wieder ein ekelhafter Tag in Tarrens Mühle. Diese ganze gesunde Luft verdirbt mir gründlich die Laune, {name}.\n\nJe schneller wir die Menschen hier erkranken lassen können, desto besser. Ich habe intensive Studien über mögliche tödliche Zutaten für meine Gebräue durchgeführt, aber ich habe nicht die Zeit, sie alle zu sammeln.\n\nWenn Ihr Euch nützlich machen wollt, dann besorgt mir Folgendes: 10 Graubärzungen sowie das sehr seltene und schwer zu findende Krabblersekret. Bären und Krabbler könnt Ihr gleich außerhalb von Tarrens Mühle finden.", sourceObjective = "Apotheker Lydon aus Tarrens Mühle möchte 10 Graubärzungen und etwas Krabblersekret.", sourceObjectiveStatus = "unverified-source-field" }
quests[498] = { id = 498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rettung", description = "Ich und einige andere Krieger wurden vom Kriegshäuptling geschickt, um ein Objekt aus Durnholde zu holen und dieses so genannte Syndikat zu untersuchen.\n\nAls wir nach Durnholde kamen, um uns umzusehen, wurden wir von einer großen Anzahl der Menschen überrascht. Wir haben mutig gekämpft, aber allein ihre Anzahl war so überwältigend groß, um uns zu besiegen. Sie haben einige von uns als Gefangene genommen, aber ich konnte entkommen.\n\nDurnholde befindet sich nicht weit südöstlich von uns, nur über den Fluss. Drull und Tog'thar werden dort gefangen gehalten, Ihr müsst sie retten.", sourceObjective = "Krusk in Tarrens Mühle braucht Euch, um Drull und Tog'thar aus der Burg Durnholde zu befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[499] = { id = 499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixier des Leidens", description = "Es wird einen Moment dauern, diese Komponenten zu vermengen, damit ein, wie ich es nenne, Elixier des Leidens entsteht.\n\nDann mal los! Ah, es gibt doch nichts Schöneres in diesem elendiglichen Vorgebirge, als ein wenig Leiden in die Welt zu bringen.\n\nLasst uns mal überprüfen, ob unser kleiner Trank auch seine gewünschte Wirkung hat.\n\nGebt meiner Assistentin Umpi einen kleinen Schluck von dem, was die Dunkle Fürstin sowohl für Menschen als auch für die Geißel geplant hat.", sourceObjective = "Gebt Umpi das Elixier des Leidens.", sourceObjectiveStatus = "unverified-source-field" }
quests[500] = { id = 500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trümmergratkopfgeld", description = "Die Trümmergratoger haben einen Ogerhort im Alteracgebirge nahe der verfallenen Stadt Alterac gebaut. Meine Späher berichteten mir, dass sie auch die Ruinen da erobert haben.\n\nWir dürfen aber nicht zulassen, dass sie sich da fest einnisten. Falls sie sich dort zu sicher fühlen, werden sie bestimmt ins Vorgebirge eindringen und wären dann praktisch vor unserer Haustür!\n\nBegebt Euch nach Norden in das Alteracgebirge auf Ogerjagd. Bringt mir die schmutzigen Knöchelknochen, die sie tragen, und Ihr habt Euch ein hübsches Kopfgeld verdient.", sourceObjective = "Sammelt 9 schmutzige Knöchelknochen von Trümmergratogern im Alteracgebirge. Bringt sie zu Marschall Rotpfad in Süderstade.", sourceObjectiveStatus = "unverified-source-field" }
quests[501] = { id = 501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixier der Schmerzen", description = "Oh, {name}..., im Hügelland blühen die Blumen und die Luft ist so klar und rein. Ich muss in diesem ganzen Elend baden. Ich sehe aus meinem verdreckten Fenster und sehne den Tag herbei, an dem unsere neue Seuche dieser Welt ihren wohlverdienten Tod bringt.\n\nSo gern ich auch den ganzen Tag hier herumsitzen und mit Grübeln verbringen würde, meine Pflicht gegenüber der Dunklen Fürstin ruft mich. Würdet Ihr mir helfen? Meine Forschungen führen mich zu der Annahme, dass sich aus Berglöwenblut ein vorzüglicher Todestrank herstellen lässt. Bringt mir etwas davon, dann können wir ein bisschen Spaß haben.", sourceObjective = "Bringt 10 Phiolen mit Berglöwenblut zu Apotheker Lydon in Tarrens Mühle.", sourceObjectiveStatus = "unverified-source-field" }
quests[502] = { id = 502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixier der Schmerzen", description = "Ah, es geht doch nichts über den Geruch von frischem Blut im Vorgebirge!\n\nDann lasst uns eine Prise davon und ein wenig hiervon vermischen - und der einzig wahre Spaß kann beginnen! Die Kreation aus diesem Blut möchte ich Elixier der Schmerzen nennen. Wenn meine Berechnungen korrekt sind, sollte dieses Gebräu der Anfang von etwas Wunderbarem für Fürstin Sylvanas sein. Aber wir müssen erstmal einen Testlauf machen.\n\nBringt dieses Elixier zum nördlichen Hof in den Feldern des Hügellands im Südwesten. Lasst uns sehen, wie Stanley, dem kleinen Hund von Bauer Ray, dieses 'Leckerli' so schmeckt.", sourceObjective = "Füttert Stanley mit dem Elixier der Schmerzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[503] = { id = 503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gol'dir", description = "Soweit ich das aus den Dokumenten, die Ihr herbrachtet, ersehen kann, wird Gol'dir in einem großen Syndikatsstützpunkt im Norden festgehalten, höchstwahrscheinlich im Alteracgebirge. Er ist schon zu lange dort gefangen und muss endlich befreit werden.", sourceObjective = "Befreit Gol'dir und kehrt dann zu Krusk in Tarrens Mühle zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[504] = { id = 504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegstreiber der Trümmergratoger", description = "Nun, da Ihr die Bekanntschaft der Trümmergratoger gemacht habt, möchte ich, dass Ihr ihnen so richtig zeigt, was eine Harke ist...\n\nGeht zu den Ruinen von Alterac und sucht die Kriegstreiber der Trümmergratoger. Ihr sollt eine große Anzahl von ihnen erschlagen - das ist der einzige Weg, um diese Schläger von dem Gebiet der Allianz fern zu halten.", sourceObjective = "Erschlagt 10 Kriegstreiber der Trümmergratoger und kehrt dann zu Marschall Rotpfad in Süderstade zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[505] = { id = 505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auftragsmörder des Syndikats", description = "Ich bin der neue Magistrat von Süderstade. Ich wurde erst kürzlich ernannt, nachdem der vorherige Magistrat ermordet worden ist. Die Mörder wurden nie gefunden, aber unsere Nachforschungen haben ergeben, dass sie höchstwahrscheinlich vom Syndikat angeworben wurden - einer Gruppe von Dieben, angeführt von schurkischen Edlen des jetzt gefallenen Königsreichs von Alterac.\n\nDas Syndikat hat Lager bei Soferas Landspitze und Corrahns Dolch, nördlich und westlich des von der Horde besetzten Tarrens Mühle. Erschlagt die Syndikatsmitglieder, die Ihr dort vorfindet.", sourceObjective = "Tötet 12 Schleicher des Syndikats und 8 Diebe des Syndikats, kehrt dann zurück zu Magistrat Henry Maleb nach Süderstade.", sourceObjectiveStatus = "unverified-source-field" }
quests[506] = { id = 506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzmoors Vermächtnis", description = "Vor ein oder zwei Tagen erhielt ich Besuch vom Anführer dieses Syndikats. Sein Name war Aliden Perenolde und er nannte sich selbst Lord dieses Landes. Er vertraute mir seine Pläne an, die Orcs, die sich gegen ihn gewandt hatten, zu Sklaven zu machen, genau wie es einst auch sein Vater und Mentor, der geächtete Schwarzmoor, geplant hatte.\n\nAber viel wichtiger war, dass er seine Geliebte mitbrachte, ein zartes Mädchen namens Elysa. Um ihren Hals trug sie den Anhänger, den der Kriegshäuptling als sein Eigen wünscht.\n\nGeht jetzt, ich gehe meine eigenen Wege, nachdem ich meine Geschäfte hier erledigt habe.", sourceObjective = "Bringt die von Gol'dir gesammelten Informationen zu Krusk in Tarrens Mühle.", sourceObjectiveStatus = "unverified-source-field" }
quests[507] = { id = 507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Aliden Perenolde", description = "Es ist unumstritten, dass Perenolde getötet werden und seine Verderbtheit ausgelöscht werden muss. Sein Herrenhaus liegt weit nördlich von hier, an den Ufern des Lordameresees. {name}, tut Eure Pflicht, holt danach den Anhänger, den der Kriegshäuptling zu haben wünscht, und kehrt dann hierher zurück.", sourceObjective = "Tötet Lord Aliden Perenolde und befragt seine Geliebte Elysa nach Tarethas Anhänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[508] = { id = 508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tarethas Geschenk", description = "Den Anhänger? Aber natürlich könnt Ihr ihn haben... Nehmt ihn! Nichts soll mich an ihn erinnern... nur bitte geht, bitte geht in Frieden...", sourceObjective = "Bringt Tarethas Anhänger zu Krusk nach Tarrens Mühle im Vorgebirge des Hügellands.", sourceObjectiveStatus = "unverified-source-field" }
quests[509] = { id = 509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixier der Pein", description = "Ein neuer Tag, ein neues Elixier. Wenn ich was zu sagen hätte, würde ich diese lächerlichen Menschen und die Geißel die Sache einfach unter sich ausmachen lassen. Sie scheinen ohnehin absolut darauf versessen zu sein, sich gegenseitig umzubringen.\n\nAber leider hat es sich unsere Dunkle Fürstin in den Kopf gesetzt, das Ganze ein wenig zu beschleunigen. Also warum diese düsteren Tage nicht dazu nutzen, um hier ein wenig Tod und Krankheit zu verbreiten?\n\n{name}, das ist mein Plan: Ihr macht Euch auf den Weg zur Nethandersiedlung. Das ist südlich von Tarrens Mühle und östlich des Flusses und Süderstade. Sammelt in den Feldern dort 6 Morastschnauzenkappen für mein nächstes Elixier.", sourceObjective = "Bringt 6 Morastschnauzenkappen zu Apotheker Lydon in Tarrens Mühle.", sourceObjectiveStatus = "unverified-source-field" }
quests[510] = { id = 510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furchteinflößende Pläne", description = "Unter diesen Dokumenten befindet sich eine Liste der benötigten Vorräte. Das sind unter anderem ganz banale Dinge (Nahrung, Waffen, Kleidung) wie auch etwas exotischere Ausrüstungsgegenstände (Masken, Öl, Gift).\n\nAber am auffälligsten ist die Dringlichkeit dieses Auftrags - diese Vorräte werden schnellstens benötigt, um eine Unternehmung zu starten, die in dem Dokument als 'wichtige Mission gegen Süderstade' beschrieben wird.", sourceObjective = "Bringt die furchteinflößenden Pläne zu Magistrat Henry Maleb nach Süderstade.", sourceObjectiveStatus = "unverified-source-field" }
quests[511] = { id = 511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlüsselter Brief", description = "Einer der Briefe auf diesem Tisch ist verschlüsselt und nicht zu ergründen.", sourceObjective = "Bringt den verschlüsselten Brief zum Meister der Lehren Dibbs nach Süderstade.", sourceObjectiveStatus = "unverified-source-field" }
quests[512] = { id = 512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod der Edlen", description = "Ich fürchte, die Führung, die hinter dem Syndikat steht, will Süderstade unbedingt ruinieren. Wir müssen diese Anführer mit aller Kraft schlagen, bevor sie ihre Pläne in die Tat umsetzen können.\n\nGeht zu den Ruinen von Strahnbrad, im Alteracgebirge im Norden. Wir glauben, dass das Syndikat dieses Gebiet als Hauptquartier benutzt.\n\nWir wissen, dass diese Bande von Halsabschneidern von ehemaligen Adligen von Alterac angeführt wird. Sie mögen sich als normale Agenten des Syndikats verkleiden, aber wenn Ihr sie tötet, werdet Ihr einen Edlen an dem Siegelring erkennen, den er trägt.\n\nBringt mir diese Siegelringe.", sourceObjective = "Bringt 7 Alteracsiegelringe zu Magistrat Henry Maleb nach Süderstade.", sourceObjectiveStatus = "unverified-source-field" }
quests[513] = { id = 513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixier der Pein", description = "Gerade dachte ich noch, ein weiterer Tag ohne jegliches Amüsement, und da kommt Ihr und bringt diese wunderbaren Morastschnauzenkappen.\n\nZuerst werde ich sie zu einem feinen Gemisch zusammenrühren. Dann werden wir Apothekermeister Faranell in Unterstadt benötigen, damit er seine Paste des Verfalls hinzufügt, und dann geht der Spaß erst richtig los!\n\nHier, {name}, nehmt dieses Morastschnauzengemisch und bringt es schnell zu Meister Faranell.", sourceObjective = "Bringt das Morastschnauzengemisch zu Apothekermeister Faranell in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[514] = { id = 514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brief an Sturmlanze", description = "Ich habe einen Kollegen in Eisenschmiede, der bei der Entschlüsselung dieses Briefes behilflich sein kann. Begebt Euch zur Bibliothek in der Halle der Forscher in Eisenschmiede und sprecht mit Ausgrabungsleiter Sturmlanze. Richtet ihm aus, dass ich Euch geschickt habe, und zeigt ihm diesen Brief. Wenn es jemanden nördlich der Schwarzfelsspitze gibt, der das hier lesen kann, dann ist er das.", sourceObjective = "Bringt den geschickt verschlüsselten Brief zu Ausgrabungsleiter Sturmlanze nach Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[515] = { id = 515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixier der Pein", description = "Ein Morastschnauzengemisch? Das ist wirklich brillant! Warum ist mir das nicht eingefallen?\n\nLasst mich meine Paste des Verfalls diesem Teufelsgebräu hinzufügen.\n\nDamit die verunreinigenden Agenzien in dieser Morastschnauzenmixtur aktiviert werden, benötigt Lydon starken Trollbluttrank sowie einige Säbelflossenschuppen und Fetzenflossenaugen von der Südküste des Hügellands. Er wird wissen, was zu tun ist, sobald Ihr alle Reagenzien zusammengetragen habt. Ich kann es kaum abwarten zu erfahren, wie sein Experiment ablaufen wird!", sourceObjective = "Bringt die Morastschnauzenmixtur, einen starken Trollbluttrank, 5 Säbelflossenschuppen und 5 Fetzenflossenaugen zu Apotheker Lydon nach Tarrens Mühle.", sourceObjectiveStatus = "unverified-source-field" }
quests[516] = { id = 516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berens List", description = "Ich habe Berichte erhalten, dass eine Gruppe Untoter sich zusammenrottet, um einen Angriff gegen uns vorzubereiten. Mit diesen Informationen können wir den Spieß umdrehen und sie zuerst angreifen, damit wäre ihr Plan erledigt.\n\nLeider sind meine Informationen gelinde gesagt unvollständig. Laut Bericht verstecken sie sich an einem Ort, der als Berens List bekannt ist. Ihr genauer Standort ist unbekannt, aber es scheint eine Höhle in den Hügeln zu sein, nahe einem Nest der Hexer von Dalaran.\n\nIch vertraue auf Euren Einfallsreichtum. Findet sie und macht alles dem Erdboden gleich.", sourceObjective = "Findet zuerst Berens List, tötet 6 Zwangsarbeiter von Rabenklaue sowie 6 Wächter von Rabenklaue und kehrt dann zu Schattenpriester Allister in das Grabmal zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[517] = { id = 517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixier der Pein", description = "Das neue Elixier ist endlich bereit für einen Test. Aber warum solch eine vollkommene, höchst ansteckende Seuche an einen einfachen Frosch oder Hund verschwenden? Wir sollten uns in Fürstin Sylvanas' Namen eine kleine Freude erlauben.\n\nGeht nach Dun Garok. Ihr kennt doch die Kasernen, in denen diese widerlichen kleinen Zwerge umhersausen. Ihr stehlt ein Fässchen Kniegräberstarkbier für mich. Sobald ich dieses Fässchen habe, können wir beide, Ihr und ich, eine kleine Party feiern, {name}.", sourceObjective = "Bringt ein Fässchen mit Kniegräberstarkbier zu Apotheker Lydon nach Tarrens Mühle.", sourceObjectiveStatus = "unverified-source-field" }
quests[518] = { id = 518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone des Willens", description = "Mug'Thol und seine Trümmergratoger haben die Ruinen von Alterac überrannt. Ihm eine schwere Strafe zukommen zu lassen, ohne die Anzahl der Oger zu verringern, wird nicht einfach sein.\n\nWir machen sie erst weich und sehen dann weiter.\n\nVerstanden? Gut. Dann geht.", sourceObjective = "Tötet 10 Raufer der Trümmergratoger für Melisara in Tarrens Mühle.", sourceObjectiveStatus = "unverified-source-field" }
quests[519] = { id = 519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone des Willens", description = "Targ, Muckrake und Glommus sind Mug'Thols Offiziere. Sie sind ihm loyal ergeben, aber wer weiß schon, was einen Oger loyal sein lässt.\n\nBringt mir ihre Köpfe, {name}, und dann muss nur noch Mug'Thols Kopf, mitsamt Krone, rollen.", sourceObjective = "Tötet Targ, Muckrake und Glommus und bringt ihre Köpfe zu Melisara nach Tarrens Mühle.", sourceObjectiveStatus = "unverified-source-field" }
quests[520] = { id = 520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone des Willens", description = "Nun, da Mug'Thols Offiziere tot sind, muss nur noch Mug'Thol selbst getötet und die Krone des Willens wieder zurückgebracht werden. Ich bin mir ziemlich sicher, dass er sie nur äußerst unwillig wieder hergeben wird. Außerdem wird er Euch wahrscheinlich bereits erwarten, in Anbetracht des... Ablebens... seiner Kumpanen.\n\nFindet Mug'Thol und bringt mir seinen Kopf und die Krone. Der Widerstand der Trümmergratoger wird damit beendet sein.", sourceObjective = "Tötet Mug'Thol und bringt seinen Kopf mit der Krone des Willens zu Melisara nach Tarrens Mühle.", sourceObjectiveStatus = "unverified-source-field" }
quests[521] = { id = 521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone des Willens", description = "Es bleibt nur noch, die Krone des Willens zu Sharlindra nach Unterstadt zu bringen. Sie wird dafür sorgen, dass sie an Fürstin Sylvanas weitergeleitet wird. Ich warne Euch, auch nur daran zu denken, sie für Eure eigenen Zwecke zu verwenden, {name}, Mug'Thols Schicksal sollte Beispiel genug sein.", sourceObjective = "Bringt die Krone des Willens zu Sharlindra in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[522] = { id = 522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auftragsmördervertrag", description = "Dies ist ein Vertrag für die Ermordung des Magistrats Henry Maleb. Er wurde mit einem unverwechselbaren Siegelring in rotem Wachs gestempelt und versiegelt.", sourceObjective = "Bringt den Auftragsmördervertrag zu Magistrat Maleb nach Süderstade.", sourceObjectiveStatus = "unverified-source-field" }
quests[523] = { id = 523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ableben des Barons", description = "Der Vertrag, den Ihr gebracht habt, wurde von Baron Vardus unterschrieben, einem Edlen aus dem ehemaligen Königreich von Alterac, und jemand der bekannt ist für seine Kaltherzigkeit und brutale Vorgehensweisen. Es überrascht mich nicht, dass jemand wie der Baron dahinter steckt.\n\nFindet diesen Mann. Findet ihn und führt ihn seiner gerechten Strafe zu. Er befindet sich sicherlich irgendwo in den Schlupfwinkeln des Syndikats - vielleicht in den Ruinen von Strahnbrad oder irgendwo in dem Tal im Norden davon.", sourceObjective = "Bringt den Kopf von Baron Vardus zu Magistrat Maleb nach Süderstade.", sourceObjectiveStatus = "unverified-source-field" }
